type Screen='home'|'works'|'recovery'|'feature'|'settings'|'editor';
export function installHomeShell(app:HTMLElement,actions:HomeActions):HomeShell{
  const root=document.createElement('div');root.id='ihApp';root.className='ih-root';root.innerHTML=html;document.body.append(root);
  if(location.pathname.replace(/\/+$/,'').endsWith('/qa/home')){
    const checks=document.createElement('details');checks.className='ih-checks';checks.innerHTML='<summary>今回の確認</summary><ol><li>作品を作り、線を描いてホームへ戻る</li><li>マイ作品から開き、線とレイヤーが残っているか見る</li><li>別の作品も作り、二つの絵が混ざらないか見る</li><li>アプリを閉じて開き直し、前回の作品を続ける</li><li>作品の名前を変え、複製・削除を試す</li><li>用紙を動かす・拡大する・回す。白い枠だけが残らないか見る</li></ol>';root.querySelector('.ih-footer')!.after(checks);
  }
  // Show the dialog over the current screen, including when Home is hidden.
  const dialog=root.querySelector<HTMLDialogElement>('#ihNewDialog')!;
  document.body.append(dialog);
  const el=<T extends HTMLElement=HTMLElement>(id:string)=>
    (dialog.querySelector<T>('#'+id)??root.querySelector<T>('#'+id))!;
  let screen:Screen='home',featureIndex=0,recovery:readonly RecoverySummary[]=[],works:readonly WorkEntry[]=[],lastWorkId:string|null=null,workUrls=new Map<string,{revision:string|null;url:string}>();
  const previewPending=new Set<string>();
  const selectedWorkIds=new Set<string>();
  let visibleWorkIds:string[]=[];
  const fetchVisiblePreview=async(work:WorkEntry)=>{
    if(!work.thumbnailRevision||work.thumbnailRevision!==work.revisionId)return;
    const id=work.documentId,revision=work.thumbnailRevision,key=id+':'+revision;
    if(previewPending.has(key)||workUrls.get(id)?.revision===revision)return;
    previewPending.add(key);
    try{
      const blob=await actions.readThumbnail(id,revision);if(!blob)return;
      const card=[...el('ihWorkGrid').querySelectorAll<HTMLElement>('.ih-work-card')].find(item=>item.dataset.workId===id);
      if(!card||card.dataset.workRevision!==revision||card.dataset.thumbnailRevision!==revision)return;
      const existing=workUrls.get(id);if(existing)URL.revokeObjectURL(existing.url);
      const url=URL.createObjectURL(blob);workUrls.set(id,{revision,url});
      const button=card.querySelector<HTMLButtonElement>('.ih-work-preview');if(!button)return;
      const img=document.createElement('img');img.alt='';img.loading='lazy';img.src=url;button.replaceChildren(img);
    }catch(error){console.warn('Preview read deferred:',error);}
    finally{previewPending.delete(key);}
  };
  const previewObserver=typeof IntersectionObserver==='undefined'?null:new IntersectionObserver(entries=>{
    for(const entry of entries)if(entry.isIntersecting){
      const element=entry.target as HTMLElement,work=works.find(w=>w.documentId===element.dataset.workId);
      if(work)void fetchVisiblePreview(work);previewObserver?.unobserve(element);
    }
  },{rootMargin:'280px'});
  const setButton=(id:string,handler:()=>void)=>{el<HTMLButtonElement>(id).addEventListener('click',handler);};
  const notify=(message:string)=>{const notice=el('ihNotice');notice.textContent=message;notice.hidden=!message;};
  const navigate=(next:Screen,writeHistory=true)=>{
    if(next==='editor'&&!actions.hasDocument()){showNew();return;}
    screen=next;const inEditor=next==='editor';
    root.hidden=inEditor;app.inert=!inEditor;app.setAttribute('aria-hidden',String(!inEditor));
    if(inEditor)requestAnimationFrame(()=>actions.onEditorVisible?.());
    for(const section of root.querySelectorAll<HTMLElement>('[data-ih-screen]'))section.hidden=section.dataset.ihScreen!==next;
    const homeNav=next==='home',worksNav=next==='works';
    el('ihNavHome').classList.toggle('is-active',homeNav);el('ihNavWorks').classList.toggle('is-active',worksNav);
    el('ihNavSettings').classList.toggle('is-active',next==='settings');
    el('ihNavHome').setAttribute('aria-current',homeNav?'page':'false');el('ihNavWorks').setAttribute('aria-current',worksNav?'page':'false');
    if(next==='works'){renderWorks();void loadWorks();}if(!inEditor){notify('');el('ihMain').scrollTop=0;root.scrollTop=0;}
    if(dialog.open)dialog.close();
    const heading=inEditor?app.querySelector<HTMLElement>('#canvas'):root.querySelector<HTMLElement>('[data-ih-screen="'+next+'"] h1');if(heading){heading.tabIndex=-1;heading.focus({preventScroll:true});}
    if(writeHistory){
      const hash=next==='feature'?'#feature/'+HOME_TRIVIA[featureIndex]!.id:'#'+next;
      if(location.hash!==hash)history.pushState({illustroScreen:next},'',hash);
    }
  };
  const showNew=(mode:'blank'|'file'='blank')=>{
    if(mode==='file'){actions.openFile();return;}
    if(dialog.open)return;
    if(templateContent){
      el<HTMLInputElement>('ihNewName').value='新しい作品';
      el<HTMLInputElement>('ihNewAuthor').value='';
      el<HTMLTextAreaElement>('ihNewDescription').value='';
    }
    refillTemplates();
    templateContent=undefined;
    el<HTMLDetailsElement>('ihCanvasSetup').open=false;
    el('ihNewError').textContent='';
    dialog.showModal();
    prefetchDraft();
  };
  const chooseTrivia=(next:number)=>{
    featureIndex=(next+HOME_TRIVIA.length)%HOME_TRIVIA.length;const card=HOME_TRIVIA[featureIndex]!;
    el('ihFeatureCounter').textContent=String(featureIndex+1).padStart(2,'0')+' / '+String(HOME_TRIVIA.length).padStart(2,'0');
    el('ihFeatureTitle').textContent=card.title;el('ihFeatureSummary').textContent=card.summary;el('ihFeatureCategory').textContent=card.kicker;el('ihFeatureMilestone').textContent=card.milestone;
    el('ihFeatureVisual').setAttribute('data-art',card.art);
  };
  const showFeature=()=>{const card=HOME_TRIVIA[featureIndex]!;
    el('ihDetailTitle').textContent=card.title;el('ihDetailSummary').textContent=card.summary;el('ihDetailCategory').textContent=card.kicker;el('ihDetailMilestone').textContent=card.milestone;
    el('ihDetailDescription').textContent=card.details;const steps=el<HTMLOListElement>('ihDetailSteps');steps.replaceChildren(...card.steps.map(step=>{const li=document.createElement('li');li.textContent=step;return li;}));navigate('feature');
  };
  const run=async(action:()=>Promise<unknown>,button?:HTMLButtonElement)=>{if(button)button.disabled=true;try{await action();}catch(error){notify(error instanceof Error?error.message:String(error));}finally{if(button)button.disabled=false;}};
  const updateBatch=()=>{
    const valid=new Set(works.map(work=>work.documentId));
    for(const id of selectedWorkIds)if(!valid.has(id))selectedWorkIds.delete(id);
    el('ihWorkBatch').hidden=selectedWorkIds.size===0;
    el('ihWorkSelectionCount').textContent=selectedWorkIds.size+'件を選択中';
    el<HTMLButtonElement>('ihWorkSelectAll').disabled=visibleWorkIds.length===0;
  };
  const renderWorks=()=>{
    const validIds=new Set(works.map(work=>work.documentId));
    for(const [id,cached] of workUrls){if(!validIds.has(id)){URL.revokeObjectURL(cached.url);workUrls.delete(id);}}
    const query=el<HTMLInputElement>('ihWorkSearch').value.trim().toLocaleLowerCase('ja-JP'),sort=el<HTMLSelectElement>('ihWorkSort').value;
    const folder=el<HTMLSelectElement>('ihWorkFolder').value;
    const favoriteOnly=el<HTMLSelectElement>('ihWorkFavorites').value==='only';
    const folderSelector=el<HTMLSelectElement>('ihWorkFolder');
    const folders=[...new Set(works.map(w=>w.catalogFolder??'').filter(Boolean))].sort((a,b)=>a.localeCompare(b,'ja-JP'));
    folderSelector.replaceChildren(new Option('すべてのフォルダー',''),...folders.map(v=>new Option(v,v)));
    if(folders.includes(folder))folderSelector.value=folder;
    const filtered=works.filter(work=>
      [work.name,work.catalogFolder??'',...(work.catalogTags??[])].join(' ').toLocaleLowerCase('ja-JP').includes(query)&&
      (!folder||work.catalogFolder===folder)&&(!favoriteOnly||work.favorite)
    ).sort((a,b)=>sort==='name'?a.name.localeCompare(b.name,'ja-JP'):
      sort==='created'?b.createdAt-a.createdAt:sort==='favorite'?(Number(!!b.favorite)-Number(!!a.favorite)||b.updatedAt-a.updatedAt):b.updatedAt-a.updatedAt);
    visibleWorkIds=filtered.map(work=>work.documentId);updateBatch();
    root.querySelector('.ih-works-count')!.textContent=works.length+'作品';(root.querySelector('.ih-empty-works') as HTMLElement).hidden=works.length>0;
    el('ihWorkNoResults').hidden=works.length===0||filtered.length>0;
    previewObserver?.disconnect();
    el('ihWorkGrid').replaceChildren(...filtered.map(work=>{
      const card=document.createElement('article');card.className='ih-work-card';card.dataset.workId=work.documentId;card.dataset.workRevision=work.revisionId;card.dataset.thumbnailRevision=work.thumbnailRevision??'';
      const open=document.createElement('button');open.type='button';open.className='ih-work-preview';open.setAttribute('aria-label',work.name+'を開く');
      const cached=workUrls.get(work.documentId);
      if(cached?.revision===work.thumbnailRevision&&work.thumbnailRevision===work.revisionId){const img=document.createElement('img');img.alt='';img.loading='lazy';img.src=cached.url;open.append(img);}
      else{open.textContent='プレビューを準備中';}
      open.onclick=()=>void run(async()=>{if(await actions.openWork(work.documentId))navigate('editor');},open);
      const info=document.createElement('div');info.className='ih-work-info';
      const title=document.createElement('button');title.type='button';title.className='ih-work-title';title.dataset.userContent='';title.textContent=work.name;title.setAttribute('aria-label',work.name+'の名前を変更');
      title.onclick=()=>showRename(work);
      const meta=document.createElement('p');
      meta.textContent=[work.favorite?'★ お気に入り':'',work.catalogFolder??'',(work.catalogTags??[]).join(' / '),
        work.width+' × '+work.height+' px',new Date(work.updatedAt).toLocaleString(uiLocale())].filter(Boolean).join(' · ');
      const details=document.createElement('div');details.className='ih-work-menu';details.popover='auto';
      const menuToggle=document.createElement('button');menuToggle.type='button';menuToggle.className='ih-work-menu-toggle';
      menuToggle.innerHTML=icon('more');menuToggle.setAttribute('aria-label',work.name+'の作品操作');
      menuToggle.setAttribute('aria-expanded','false');menuToggle.popoverTargetElement=details;
      details.addEventListener('beforetoggle',event=>{
        const opening=(event as ToggleEvent).newState==='open';
        menuToggle.setAttribute('aria-expanded',String(opening));
        if(!opening)return;
        const rect=menuToggle.getBoundingClientRect();
        const width=Math.min(220,innerWidth-16);
        details.style.width=width+'px';
        details.style.left=Math.max(8,Math.min(rect.right-width,innerWidth-width-8))+'px';
        details.style.top=Math.max(8,Math.min(rect.bottom+4,innerHeight-264))+'px';
      });
      for(const [glyph,label,action] of [
        ['document','名前を変更',async()=>showRename(work)],
        ['effects',work.favorite?'お気に入りを解除':'お気に入り',async()=>{
          await actions.updateWorkCatalog(work.documentId,{favorite:!work.favorite});await loadWorks();
        }],
        ['open','整理する',async()=>{
          const folder=await appPrompt('フォルダー名（空欄なら未分類）',work.catalogFolder??'');if(folder===null)return;
          const tags=await appPrompt('タグ（カンマで区切ってください）',(work.catalogTags??[]).join(', '));if(tags===null)return;
          await actions.updateWorkCatalog(work.documentId,{folder,tags:tags.split(/[,、，]+/)});await loadWorks();
        }],
        ['copy','複製',async()=>{await actions.duplicateWork(work.documentId);await loadWorks();}],
        ['trash','ゴミ箱へ移動',async()=>{await actions.deleteWork(work.documentId);await loadWorks();await loadTrash();}]
      ] as const){
        const button=document.createElement('button');button.type='button';button.innerHTML=icon(glyph);
        button.append(document.createTextNode(label));button.dataset.workAction=label;
        button.onclick=()=>{details.hidePopover();menuToggle.focus({preventScroll:true});void run(action,menuToggle);};
        details.append(button);
      }
      const select=document.createElement('label');select.className='ih-work-pick';
      const checkbox=document.createElement('input');checkbox.type='checkbox';
      checkbox.checked=selectedWorkIds.has(work.documentId);
      checkbox.setAttribute('aria-label',work.name+'をまとめて操作する対象に選ぶ');
      checkbox.onchange=()=>{
        if(checkbox.checked)selectedWorkIds.add(work.documentId);
        else selectedWorkIds.delete(work.documentId);
        updateBatch();
      };
      select.append(checkbox,' 選択');
      info.append(title,meta,menuToggle,details);card.append(select,open,info);return card;
    }));
    for(const element of el('ihWorkGrid').querySelectorAll<HTMLElement>('.ih-work-card')){
      const work=filtered.find(w=>w.documentId===element.dataset.workId);
      if(!work||workUrls.get(work.documentId)?.revision===work.thumbnailRevision)continue;
      if(previewObserver)previewObserver.observe(element);
      else void fetchVisiblePreview(work);
    }
  };
  const selectedWorks=()=>works.filter(work=>selectedWorkIds.has(work.documentId));
  const batchAction=(id:string,action:()=>Promise<void>)=>{
    const button=el<HTMLButtonElement>(id);
    button.onclick=()=>void run(async()=>{
      try{await action();}
      finally{await loadWorks();updateBatch();}
    },button);
  };
  el<HTMLButtonElement>('ihWorkSelectAll').onclick=()=>{
    for(const id of visibleWorkIds)selectedWorkIds.add(id);
    renderWorks();
  };
  el<HTMLButtonElement>('ihWorkClearSelected').onclick=()=>{
    selectedWorkIds.clear();renderWorks();
  };
  el<HTMLButtonElement>('ihWorkExportSelected').onclick=()=>actions.exportWorks(selectedWorks());
  batchAction('ihWorkMoveSelected',async()=>{
    const selected=selectedWorks();if(!selected.length)return;
    const folder=await appPrompt(selected.length+'件の作品を移動するフォルダー名（空欄なら未分類）');
    if(folder===null)return;
    for(const work of selected){
      await actions.updateWorkCatalog(work.documentId,{folder});
      selectedWorkIds.delete(work.documentId);
    }
    notify(selected.length+'件のフォルダーを変更しました。');
  });
  batchAction('ihWorkFavoriteSelected',async()=>{
    const selected=selectedWorks();if(!selected.length)return;
    for(const work of selected){
      await actions.updateWorkCatalog(work.documentId,{favorite:true});
      selectedWorkIds.delete(work.documentId);
    }
    notify(selected.length+'件をお気に入りにしました。');
  });
  batchAction('ihWorkTrashSelected',async()=>{
    const selected=selectedWorks();if(!selected.length)return;
    for(const work of selected){
      await actions.deleteWork(work.documentId);
      selectedWorkIds.delete(work.documentId);
    }
    await loadTrash();
    notify(selected.length+'件をゴミ箱へ移動しました。');
  });
  const setWorks=(values:readonly WorkEntry[],last:string|null)=>{works=values;lastWorkId=last;if(screen==='works')renderWorks();};
  const loadWorks=async()=>{el('ihWorksLoading').hidden=false;try{const value=await actions.listWorks();setWorks(value.works,value.lastWorkId);}catch(error){notify('作品一覧を読み込めませんでした。'+String(error));}finally{el('ihWorksLoading').hidden=true;}};
  async function loadTrash(){
    const grid=el('ihWorkTrashGrid');grid.textContent='ゴミ箱を確認しています。';
    try{
      const trashed=await actions.listTrashedWorks();
      grid.replaceChildren();
      if(!trashed.length){grid.textContent='ゴミ箱は空です。';return;}
      for(const work of trashed){
        const row=document.createElement('div');row.className='ih-work-trash-entry';
        const title=document.createElement('strong');title.dataset.userContent='';title.textContent=work.name;
        const meta=document.createElement('small');
        meta.textContent=work.trashedAt?new Date(work.trashedAt).toLocaleString(uiLocale()):'';
        const restore=document.createElement('button');restore.type='button';restore.textContent='復元する';
        restore.onclick=()=>void run(async()=>{
          await actions.restoreWork(work.documentId);await loadTrash();await loadWorks();notify('作品を元に戻しました。');
        },restore);
        const purge=document.createElement('button');purge.type='button';purge.textContent='完全に削除';
        purge.onclick=()=>void run(async()=>{
          if(!await appConfirm('「'+work.name+'」を完全に削除しますか？\n元に戻せなくなります。'))return;
          await actions.purgeWork(work.documentId);await loadTrash();await loadWorks();
          notify('作品を完全に削除しました。');
        },purge);
        row.append(title,meta,restore,purge);grid.append(row);
      }
    }catch(error){grid.textContent='ゴミ箱を確認できませんでした。'+String(error);}
  }
  el('ihWorkTrash').addEventListener('toggle',()=>{
    if((el('ihWorkTrash') as HTMLDetailsElement).open)void loadTrash();
  });
  el('ihWorkSearch').addEventListener('input',renderWorks);
  for(const id of ['ihWorkSort','ihWorkFolder','ihWorkFavorites'])el(id).addEventListener('change',renderWorks);
  const reset=el<HTMLButtonElement>('ihWorksReset');
  // The independent review build always exposes its reset control. Main builds
  // keep it hidden unless explicitly requested for debugging.
  const isMyWorksQa=location.pathname.includes('/qa/my-works-open/');
  reset.hidden=!isMyWorksQa&&new URLSearchParams(location.search).get('debugWorks')!=='1';
  reset.onclick=async()=>{
    if(!await appConfirm('マイ作品を初期化しますか？\\nアプリ内の全作品・復旧データを削除します。元に戻せません。\\n書き出した .illustro ファイルは削除されません。'))return;
    void run(async()=>{await actions.resetWorks();recovery=[];setWorks([],null);await loadWorks();notify('マイ作品を初期化しました。');},reset);
  };
  const rename=document.createElement('dialog');rename.className='ih-new-dialog';rename.setAttribute('aria-label','作品名を変更');rename.innerHTML='<form class="ih-dialog-content"><h2>作品名を変更</h2><label class="ih-name-field">作品名<input name="title" maxlength="120" required></label><p role="status"></p><div class="ih-dialog-actions"><button type="button" class="ih-quiet-button">キャンセル</button><button type="submit" class="ih-solid-button">変更する</button></div></form>';root.append(rename);
  let renamedWork:WorkEntry|null=null;
  const showRename=(work:WorkEntry)=>{renamedWork=work;rename.querySelector<HTMLInputElement>('input')!.value=work.name;rename.querySelector('p')!.textContent='';rename.showModal();rename.querySelector<HTMLInputElement>('input')!.focus();};
  rename.querySelector<HTMLButtonElement>('button[type=button]')!.onclick=()=>rename.close();
  rename.querySelector('form')!.onsubmit=event=>{event.preventDefault();if(!renamedWork)return;const work=renamedWork,button=rename.querySelector<HTMLButtonElement>('button[type=submit]')!;void run(async()=>{try{await actions.renameWork(work.documentId,rename.querySelector<HTMLInputElement>('input')!.value);rename.close();await loadWorks();}catch(error){rename.querySelector('p')!.textContent=error instanceof Error?error.message:String(error);}},button);};
  const recoveryPreviewUrls=new Set<string>();
  const showRecovery=(continueLast=false)=>{void run(async()=>{
    const last=works.find(x=>x.documentId===lastWorkId);
    const newer=last?recovery.filter(x=>x.documentId===last.documentId&&x.writerEpochId!==last.writerEpochId&&x.updatedAt>last.updatedAt):recovery;
    if(continueLast&&last&&!newer.length){if(await actions.openWork(last.documentId))navigate('editor');return;}
    const list=el('ihRecoveryList');list.replaceChildren();
    const interruptions=readInputInterruptions();
    if(interruptions.length){
      const details=document.createElement('details'),title=document.createElement('summary'),events=document.createElement('ul');
      title.textContent='入力が途切れたときの記録';
      for(const entry of interruptions){
        const item=document.createElement('li'),date=new Date(entry.at).toLocaleString(uiLocale());
        item.textContent=date+' · '+entry.work+' · '+(entry.keep?'途中まで残す操作を選択':'途中の線を取り消し');
        events.append(item);
      }
      details.append(title,events);list.append(details);
