    for(const url of recoveryPreviewUrls)URL.revokeObjectURL(url);
    recoveryPreviewUrls.clear();
    if(last){
      const button=document.createElement('button');button.type='button';button.className='ih-recovery-item';
      button.textContent=last.name+' — マイ作品の保存から続ける';
      button.onclick=()=>void run(async()=>{if(await actions.openWork(last.documentId))navigate('editor');},button);
      list.append(button);
    }
    const valid=continueLast?newer:recovery;
    if(!valid.length&&!last){
      const empty=document.createElement('p');empty.textContent='復元できる作業はありません。';list.append(empty);
    }
    for(const item of valid){
      const card=document.createElement('section'),title=document.createElement('h2');
      const status=document.createElement('p'),actionsRow=document.createElement('div');
      const button=document.createElement('button');button.type='button';button.className='ih-quiet-button';
      card.className='ih-recovery-item';
      title.textContent=item.title||'名前のない作品';
      const date=item.updatedAt?new Date(item.updatedAt).toLocaleString(uiLocale()):'時刻不明';
      status.textContent=date+' · 記録 '+item.protectedThrough+'件。プレビューで復元内容を確認できます。';
      status.setAttribute('aria-live','polite');
      button.textContent='復元コピーを開く';
      button.onclick=()=>void run(async()=>{if(await actions.resume(item.documentId,item.writerEpochId)===true)navigate('editor');},button);
      if(actions.previewRecovery){
        const preview=document.createElement('button');preview.type='button';preview.className='ih-quiet-button';
        preview.textContent='プレビューを確認';
        preview.onclick=()=>void run(async()=>{
          status.textContent=date+' · 復元内容を読み込んでいます。';
          try{
            const blob=await actions.previewRecovery!(item.documentId,item.writerEpochId);
            if(!card.isConnected)return;
            const image=new Image(),url=URL.createObjectURL(blob);
            recoveryPreviewUrls.add(url);
            image.src=url;image.alt=title.textContent+'の復元プレビュー';image.className='ih-recovery-preview';
            card.insertBefore(image,actionsRow);
            status.textContent=date+' · 復元内容を読み込めました。';
            preview.remove();
          }catch{
            if(card.isConnected)status.textContent=date+' · プレビューを作成できませんでした。';
          }
        },preview);
        actionsRow.append(preview);
      }
      actionsRow.append(button);card.append(title,status,actionsRow);list.append(card);
    }
    navigate('recovery');
  });};
  const setRecoveryCandidates=(candidates:readonly RecoverySummary[])=>{
    recovery=candidates.filter(x=>{try{return BigInt(x.protectedThrough)>0n;}catch{return false;}});
    if(screen==='recovery')showRecovery();
  };
  const showHome=async()=>{
    const leavingEditor=screen==='editor';
    navigate('home');
    if(leavingEditor)void actions.prepareHome().catch(error=>notify('作品情報を更新できませんでした。'+String(error)));
  };

  setButton('ihBrand',()=>void showHome());setButton('ihNavHome',()=>void showHome());setButton('ihNavWorks',()=>navigate('works'));
  setButton('ihNavSettings',()=>navigate('settings'));setButton('ihStart',()=>showNew());
  setButton('ihMyWorks',()=>navigate('works'));setButton('ihWorksRecovery',()=>showRecovery());
  const colorSettings=document.getElementById('workspaceColorSettings');
  if(colorSettings)el('ihColorSettings').append(colorSettings);
  setButton('ihWorksStart',()=>showNew());setButton('ihSettingsEditor',()=>actions.hasDocument()?navigate('editor'):showNew());
  setButton('ihFeaturePrev',()=>chooseTrivia(featureIndex-1));setButton('ihFeatureNext',()=>chooseTrivia(featureIndex+1));
  setButton('ihFeatureVisual',showFeature);setButton('ihFeatureMore',showFeature);
  setButton('ihDetailEditor',()=>actions.hasDocument()?navigate('editor'):showNew());
  setButton('ihNewClose',()=>dialog.close());setButton('ihNewCancel',()=>dialog.close());
  const createButton=el<HTMLButtonElement>('ihNewCreate');
  const closeButtons=[el<HTMLButtonElement>('ihNewClose'),el<HTMLButtonElement>('ihNewCancel')];
  dialog.addEventListener('keydown',event=>event.stopPropagation());
  dialog.addEventListener('cancel',event=>{if(createButton.disabled)event.preventDefault();});
  setButton('ihSelectFile',actions.openFile);
  let draftTimer:ReturnType<typeof setTimeout>|null=null;
  let currentUnit:DocumentUnit='px';
  const templateStore=(()=>{try{return localStorage;}catch{return null;}})();
  const templatePicker=el<HTMLSelectElement>('ihTemplateSelect');
  let templateContent:TemplateContent|undefined;
  const refillTemplates=(selected='')=>{
    templatePicker.replaceChildren(new Option('選択してください',''),...listCreationTemplates(templateStore).map(x=>new Option(x.name,x.name)));
    templatePicker.value=selected;
  };
  const size=()=>resolveDocumentDimensions(
    Number(el<HTMLInputElement>('ihNewWidth').value),
    Number(el<HTMLInputElement>('ihNewHeight').value),
    currentUnit,Number(el<HTMLInputElement>('ihNewDpi').value));
  const background=()=>el<HTMLSelectElement>('ihNewBackground').value as 'transparent'|'white';
  const author=()=>el<HTMLInputElement>('ihNewAuthor').value.trim();
  const description=()=>el<HTMLTextAreaElement>('ihNewDescription').value.trim();
  const sizePreview=()=>{
    try{
      const d=size(),scale=d.dpi/25.4;
      const rounded=currentUnit==='mm'&&[
        [el<HTMLInputElement>('ihNewWidth').valueAsNumber,d.width],
        [el<HTMLInputElement>('ihNewHeight').valueAsNumber,d.height],
      ].some(([mm,px])=>Math.abs(mm!*scale-px!)>.0001);
      el('ihSizeSummary').textContent=d.width+' × '+d.height+' px';
      let divisor=d.width,remainder=d.height;
      while(remainder){[divisor,remainder]=[remainder,divisor%remainder];}
      el('ihPixelPreview').textContent=d.width+' × '+d.height+' px · '+d.dpi+' DPI · 用紙比 '+
        d.width/divisor+' : '+d.height/divisor+(rounded?'（端数は最も近い画素に丸めます）':'');
      return d;
    }
    catch(error){el('ihSizeSummary').textContent='サイズを確認';el('ihPixelPreview').textContent=error instanceof Error?error.message:String(error);return null;}
  };
  const prefetchDraft=()=>{
    if(draftTimer!==null){clearTimeout(draftTimer);draftTimer=null;}
    const d=sizePreview();if(d)actions.onBlankDraftChange?.(d.width,d.height,el<HTMLInputElement>('ihNewName').value,background(),d.dpi,author(),description());
  };
  const schedulePrefetch=()=>{
    if(draftTimer!==null)clearTimeout(draftTimer);
    draftTimer=setTimeout(prefetchDraft,180);
  };
  const setFromPixels=(width:number,height:number)=>{
    const dpi=Number(el<HTMLInputElement>('ihNewDpi').value);
    el<HTMLInputElement>('ihNewWidth').value=String(currentUnit==='mm'?pixelToMillimeters(width,dpi):width);
    el<HTMLInputElement>('ihNewHeight').value=String(currentUnit==='mm'?pixelToMillimeters(height,dpi):height);
    prefetchDraft();
  };
  for(const preset of root.querySelectorAll<HTMLButtonElement>('[data-ih-preset]'))preset.addEventListener('click',()=>{
    const [width,height]=preset.dataset.ihPreset!.split('x').map(Number);
    setFromPixels(width!,height!);
    for(const item of root.querySelectorAll<HTMLButtonElement>('[data-ih-preset]'))item.setAttribute('aria-pressed',String(item===preset));
  });
  const refreshPresetSelection=()=>{
    const d=sizePreview();
    for(const preset of root.querySelectorAll<HTMLButtonElement>('[data-ih-preset]')){
      const [w,h]=preset.dataset.ihPreset!.split('x').map(Number);
      preset.setAttribute('aria-pressed',String(d!==null&&d.width===w&&d.height===h));
    }
    schedulePrefetch();
  };
  for(const input of [el<HTMLInputElement>('ihNewWidth'),el<HTMLInputElement>('ihNewHeight')])input.addEventListener('input',refreshPresetSelection);
  const setUnit=(unit:DocumentUnit)=>{
    currentUnit=unit;el<HTMLSelectElement>('ihNewUnit').value=unit;
    for(const id of ['ihNewWidth','ihNewHeight']){
      const input=el<HTMLInputElement>(id);
      input.step=currentUnit==='mm'?'any':'1';input.min=currentUnit==='mm'?'0.000001':'1';input.max=currentUnit==='mm'?'208077':'8192';
    }
  };
  el<HTMLSelectElement>('ihNewUnit').addEventListener('change',()=>{
    const before=sizePreview();setUnit(el<HTMLSelectElement>('ihNewUnit').value as DocumentUnit);
    if(before)setFromPixels(before.width,before.height);else prefetchDraft();
  });
  const dpiInput=el<HTMLInputElement>('ihNewDpi');
  let lastValidDpi=dpiInput.valueAsNumber;
  dpiInput.addEventListener('input',()=>{
    const next=dpiInput.valueAsNumber;
    if(!Number.isInteger(next)||next<1||next>2400){sizePreview();return;}
    if(currentUnit==='mm'){
      const w=el<HTMLInputElement>('ihNewWidth').valueAsNumber,h=el<HTMLInputElement>('ihNewHeight').valueAsNumber;
      if(w>0&&h>0){
        el<HTMLInputElement>('ihNewWidth').value=String(Number((w*lastValidDpi/next).toFixed(6)));
        el<HTMLInputElement>('ihNewHeight').value=String(Number((h*lastValidDpi/next).toFixed(6)));
      }
    }
    lastValidDpi=next;refreshPresetSelection();
  });
  setButton('ihA4Preset',()=>{
    setUnit('mm');dpiInput.value=String(lastValidDpi=300);
    el<HTMLInputElement>('ihNewWidth').value='210';el<HTMLInputElement>('ihNewHeight').value='297';
    refreshPresetSelection();
  });
  for(const id of ['ihNewName','ihNewDpi','ihNewAuthor','ihNewDescription'])el(id).addEventListener('input',schedulePrefetch);
  const emptyLayers=el<HTMLInputElement>('ihNewEmptyLayers');
  const refreshEmptyLayers=()=>{emptyLayers.disabled=background()!=='transparent';};
  el<HTMLSelectElement>('ihNewBackground').addEventListener('change',()=>{refreshEmptyLayers();prefetchDraft();});
  templatePicker.addEventListener('change',()=>{
    const template=listCreationTemplates(templateStore).find(x=>x.name===templatePicker.value);
    const previous=templateContent;
    templateContent=template?.content;
    if(!template&&!previous)return;
    const title=el<HTMLInputElement>('ihNewName'),authorInput=el<HTMLInputElement>('ihNewAuthor');
    const descriptionInput=el<HTMLTextAreaElement>('ihNewDescription');
    title.value=templateContent?.title??'新しい作品';
    authorInput.value=templateContent?.author??'';
    descriptionInput.value=templateContent?.description??'';
    if(!template){el('ihNewError').textContent='テンプレートの追加設定を解除しました。';return;}
    // Stored templates retain exact pixel dimensions even if the dialog was in mm mode.
    setUnit('px');dpiInput.value=String(lastValidDpi=template.dpi);
    el<HTMLSelectElement>('ihNewBackground').value=template.background;refreshEmptyLayers();
    setFromPixels(template.width,template.height);refreshPresetSelection();
    const items=['サイズ・背景',...(templateContent?.guides?.length?['定規']:[]),
      ...(templateContent?.palette?['作品パレット']:[]),...(templateContent?.title?['作品情報']:[])];
    el('ihNewError').textContent=items.join('、')+'を読み込みました。';
  });
  el<HTMLButtonElement>('ihTemplateSave').onclick=()=>{
    try{
      const d=size(),name=el<HTMLInputElement>('ihTemplateName').value.trim();
      storeCreationTemplate(templateStore,{...d,name,background:background()});
      refillTemplates(name);el('ihNewError').textContent='この端末に設定を保存しました。';
    }catch(error){el('ihNewError').textContent=error instanceof Error?error.message:String(error);}
  };
  el<HTMLButtonElement>('ihTemplateDelete').onclick=()=>{
    if(!templatePicker.value)return;
    try{removeCreationTemplate(templateStore,templatePicker.value);templateContent=undefined;refillTemplates();el('ihNewError').textContent='設定を削除しました。';}
    catch(error){el('ihNewError').textContent=error instanceof Error?error.message:String(error);}
  };
  const lastSetupKey='illustro.last-canvas-setup.v1';
  try{
    const last=JSON.parse(templateStore?.getItem(lastSetupKey)??'null');
    if(last){
      const d=resolveDocumentDimensions(last.width,last.height,last.unit,last.dpi);
      setUnit(last.unit);dpiInput.value=String(lastValidDpi=d.dpi);
      el<HTMLInputElement>('ihNewWidth').value=String(last.width);
      el<HTMLInputElement>('ihNewHeight').value=String(last.height);
      if(last.background==='white')el<HTMLSelectElement>('ihNewBackground').value='white';
      sizePreview();
    }
  }catch{}
  refillTemplates();refreshEmptyLayers();
  el<HTMLFormElement>('ihBlankForm').addEventListener('invalid',event=>{
    if(!(event.target instanceof HTMLElement))return;
    const setup=event.target.closest<HTMLDetailsElement>('#ihCanvasSetup');
    if(setup)setup.open=true;
  },true);
  el<HTMLFormElement>('ihBlankForm').addEventListener('submit',event=>{event.preventDefault();void(async()=>{
    if(createButton.disabled)return;
    const d=sizePreview();if(!d){el('ihNewError').textContent='サイズと解像度を確認してください。';return;}
    createButton.disabled=true;
    for(const button of closeButtons)button.disabled=true;
    el('ihNewError').textContent='キャンバスを準備しています。';
    try{
      const name=el<HTMLInputElement>('ihNewName').value;
      const setup={width:el<HTMLInputElement>('ihNewWidth').valueAsNumber,height:el<HTMLInputElement>('ihNewHeight').valueAsNumber,
        unit:currentUnit,background:background(),dpi:d.dpi};
      if(await actions.createDocument(d.width,d.height,name,setup.background,d.dpi,author(),description(),setup.background==='transparent'&&el<HTMLInputElement>('ihNewEmptyLayers').checked,templateContent)){
        try{templateStore?.setItem(lastSetupKey,JSON.stringify(setup));}catch{}
        navigate('editor');
      }
      else el('ihNewError').textContent='作成できませんでした。描画画面の状態を確認してください。';
    }catch(error){console.error('C01_CREATE_DOCUMENT_FAULT',error instanceof Error?error.stack??error.message:error);el('ihNewError').textContent=error instanceof Error?error.message:'作成できませんでした。';}
    finally{
      createButton.disabled=false;
      for(const button of closeButtons)button.disabled=false;
    }
  })();});
  let swipeStart:number|null=null;
  el('ihFeatureVisual').addEventListener('touchstart',event=>{swipeStart=event.touches[0]?.clientX??null;},{passive:true});
  el('ihFeatureVisual').addEventListener('touchend',event=>{if(swipeStart===null)return;const delta=(event.changedTouches[0]?.clientX??swipeStart)-swipeStart;swipeStart=null;if(Math.abs(delta)>48){chooseTrivia(featureIndex+(delta<0?1:-1));event.preventDefault();}},{passive:false});
  addEventListener('popstate',()=>{void(async()=>{
    if(screen==='editor')void actions.prepareHome().catch(error=>notify('作品情報を更新できませんでした。'+String(error)));
    const value=location.hash.replace(/^#/,'');
    if(value.startsWith('feature/')){const index=HOME_TRIVIA.findIndex(x=>x.id===value.slice(8));if(index>=0){chooseTrivia(index);showFeature();return;}}
    if(value==='works'||value==='recovery'||value==='settings')navigate(value,false);
    else if(value==='editor'&&actions.hasDocument())navigate('editor',false);
    else navigate('home',false);
  })();});
  chooseTrivia(0);setRecoveryCandidates([]);
  // The old milestone QA pages do not install this shell; normal startup is Home.
  const initial=location.hash.replace(/^#/,'');
  navigate(initial==='works'||initial==='settings'||initial==='recovery'?initial:'home',location.hash!==('#'+(initial==='works'||initial==='settings'||initial==='recovery'?initial:'home')));
  installLanguageSettings(el('ihLanguageSettings'),renderWorks);
  return {showHome,showEditor:()=>navigate('editor'),showNew,showRecovery,setRecoveryCandidates,setWorks,notify};
}

style.css:
/* M07 editor structural foundation.
 * Brand-specific colors and tool states belong to ui/aurora.css.
 * This stylesheet deliberately has no legacy yellow / olive theme.
 */
*{box-sizing:border-box}
html,body,#app{margin:0;min-height:100%}
button,input,select,textarea{font:inherit}
button{padding:8px;border:1px solid var(--a-border,#dfe5ef);border-radius:8px;background:var(--a-surface,#fff);color:inherit;cursor:pointer}
button:disabled{cursor:not-allowed;color:var(--a-subtle,#627086);background:var(--a-surface-soft,#f8faff)}
button:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible,summary:focus-visible{
 outline:3px solid var(--a-focus,#5865cc);outline-offset:2px
}
label{display:block;margin:9px 0;font-size:13px}
input[type=range],select,input[type=number],textarea{width:100%;margin-top:6px}
input[type=checkbox]{width:auto}
details{border:1px solid var(--a-border,#dfe5ef);border-radius:8px;background:var(--a-surface,#fff);margin-bottom:7px;padding:9px}
summary{cursor:pointer}
details p{font-size:13px}
.surface{position:relative}
.layer-list{display:grid;gap:5px;margin:9px 0}
.layer-entry{display:grid;grid-template-columns:minmax(0,1fr) auto auto;align-items:stretch;gap:4px}
.layer-entry>button{min-height:40px}
.layer-group-row{display:flex;flex-wrap:wrap;gap:4px;align-items:center;background:var(--a-surface-soft,#f8faff);border-radius:8px;padding:4px}
.layer-group-row button:first-child{flex:1 1 105px;text-align:left;min-width:0;overflow-wrap:anywhere}
.layer-drop-target{outline:2px solid var(--a-accent,#596bd8);outline-offset:-2px;border-radius:8px}
.layer-page-fields{display:flex;flex-wrap:wrap;align-items:center;gap:8px 16px}
.layer-page-fields label{display:flex;align-items:center;gap:8px;max-width:100%}
.layer-page-fields input{min-width:0}
#layerComps,#layerVectorMask{margin:8px 0;max-height:40%;overflow:auto;flex-shrink:0}
#layerComps label,#layerVectorMask label{display:inline-flex;align-items:center;gap:4px;max-width:100%;margin-inline-end:8px}
#layerComps input,#layerComps select{min-width:0;max-width:100%}
#layerCompStatus{display:block}
.layer-mode-actions{display:flex;flex-wrap:wrap;align-items:center;gap:6px;margin-top:8px}
.layer-batch-actions:not([hidden]){display:flex;flex-wrap:wrap;align-items:center;gap:4px;margin-top:6px}
.layer-row{width:100%;min-height:40px;display:flex;align-items:center;justify-content:space-between;gap:8px;text-align:left;padding:7px 9px;border-left:4px solid transparent}
.layer-name{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.layer-state{font-size:11px;font-weight:700;white-space:nowrap}
.layer-row[data-color-tag="red"]{border-left-color:#cb3b47}
.layer-row[data-color-tag="orange"]{border-left-color:#e47325}
.layer-row[data-color-tag="yellow"]{border-left-color:#bc8a00}
.layer-row[data-color-tag="green"]{border-left-color:#32815b}
.layer-row[data-color-tag="blue"]{border-left-color:#3373bd}
.layer-row[data-color-tag="purple"]{border-left-color:#8a53bc}
.layer-row[aria-pressed=false] .layer-state:empty::after{content:' ';white-space:pre}
.compact-only{display:none}
#splitter{position:fixed;right:var(--workspace);top:var(--top);bottom:var(--bottom);width:8px;cursor:ew-resize;touch-action:none;z-index:9}
.qa-panel{position:static;width:auto;min-width:0;max-height:none;overflow:visible;box-shadow:none;background:transparent}
.qa-panel>summary{font-weight:700}
.qa-panel ol{padding-left:22px;font-size:13px;line-height:1.55}
.qa-panel textarea{resize:vertical}
.qa-panel button{width:100%}
.qa-auto{margin-top:8px;background:var(--a-surface-soft,#f8faff)}
.qa-auto pre{white-space:pre-wrap;word-break:break-word;font-size:11px;line-height:1.4}
.bottom{display:none}
/* M06 export functionality, refreshed with the same Aurora tokens used by M07. */
.export-dialog{
 border:1px solid var(--a-border-strong,#ced8e7);border-radius:14px;
 background:var(--a-surface,#fff);color:var(--a-text,#222c40);
 box-sizing:border-box;width:min(428px,calc(100vw - 32px));max-width:calc(100vw - 32px);
 max-height:calc(100dvh - 32px);overflow:auto;padding:20px;
 box-shadow:0 15px 48px #2d3b6533
}
.export-dialog::backdrop{background:#2636548c}
.export-dialog h2{font-size:19px;margin:0 0 8px}
.export-dialog p{font-size:13px;line-height:1.6}
.export-dialog select,.export-dialog input[type=range]{min-height:35px}
.export-dialog label{font-size:14px;font-weight:600}
.export-dialog #exportTransparencyInfo{background:var(--a-accent-soft,#e9eeff);padding:10px;border-radius:8px}
.export-actions{display:flex;gap:10px;justify-content:flex-end;margin-top:16px;flex-wrap:wrap}
.export-actions button{min-height:42px;padding:9px 15px}
#exportRun{background:var(--a-accent-soft,#e9eeff);border-color:var(--a-border-strong,#ced8e7);font-weight:700}
#exportStatus{min-height:20px;overflow-wrap:anywhere}
@media(max-width:760px){
 .compact-only{display:block}
 #splitter{display:none}
 .bottom{
  position:fixed;left:var(--rail);right:env(safe-area-inset-right);bottom:0;
  display:flex;height:calc(var(--bottom) + env(safe-area-inset-bottom));
  padding:5px 5px calc(5px + env(safe-area-inset-bottom));gap:5px;
  background:var(--a-surface-soft,#f8faff);z-index:12;
 }
 .bottom button{flex:1;min-width:0;font-size:12px}
 .export-dialog{padding:16px}
}
@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto}}

.artwork-history-dialog{width:min(88vw,920px);max-height:90dvh}
.artwork-history-dialog select{max-width:100%}
.artwork-history-previews{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,220px),1fr));gap:12px}
.artwork-history-previews figure{margin:0;min-width:0}
.history-image-viewport{position:relative;height:clamp(150px,34dvh,450px);overflow:hidden;touch-action:none;cursor:grab;background:#edf0f3}
.history-image-viewport img{position:absolute;inset:0 auto auto 0;max-width:none;max-height:none;transform-origin:0 0;pointer-events:none}
.history-image-controls{display:flex;flex-wrap:wrap;gap:.3rem}
.history-pinned:not([hidden]){display:flex;gap:.4rem;overflow:auto}
.history-pinned button{display:flex;flex-direction:column;align-items:start;justify-content:end;min-width:96px;gap:.25rem}
.history-pinned img{width:96px;height:72px;object-fit:contain}

#layerPage{overflow-y:auto}
#layerPageList{flex:1 0 120px;min-height:120px}

.history-cleanup-list { max-height: 25dvh; overflow: auto; }


/* C03-012: history can stay open while the user works on the canvas. */
.artwork-history-panel[open]:not(:modal){
 position:fixed;
 inset:auto max(12px,env(safe-area-inset-right)) max(12px,env(safe-area-inset-bottom)) auto;
 margin:0;width:min(440px,calc(100vw - 24px));max-width:calc(100vw - 24px);
 max-height:min(85dvh,740px);z-index:35;
}
.artwork-history-panel .history-image-viewport{height:clamp(128px,24dvh,300px)}
@media(max-width:540px){.artwork-history-panel[open]:not(:modal){max-height:66dvh}}

/* Layer-page only: direct edit buttons for layers that already contain
 * a transform, image link or mask. Keep the primary name and controls stable. */
.layer-edit-shortcut{padding:5px 7px;min-width:40px;white-space:nowrap;font-size:12px}

ui/paintingWorkspace.css:
/* Shared painting controls stay in reach while auxiliary panels sit over the canvas. */
:root {
  --top: 56px;
  --bottom: calc(52px + env(safe-area-inset-bottom, 0px));
}
.topbar {
  gap: 4px;
  padding-inline: max(8px, env(safe-area-inset-left)) max(8px, env(safe-area-inset-right));
}
.topbar button, .drawing-controls button {
  display: inline-flex;
  flex: none;
  align-items: center;
  justify-content: center;
  gap: 6px;
  min-width: 44px;
  min-height: 44px;
  padding: 4px 8px;
  font-weight: 650;
  white-space: nowrap;
}
.topbar button[aria-expanded="true"],
.drawing-controls button[aria-expanded="true"],
body:has(#panView[aria-pressed="true"]) #viewActionsOpen {
  background: var(--a-accent-soft);
  border-color: var(--a-border-strong);
}
.current-color {
  width: 24px;
  height: 24px;
  flex: none;
  border-radius: 50%;
  background: var(--current-paint-color, #1f2633);
  border: 1px solid #5c6c83;
  box-shadow: 0 0 0 2px var(--a-surface), 0 0 0 3px var(--a-border-strong);
}
.rail {
  overflow-y: auto;
  overscroll-behavior: contain;
  scrollbar-width: thin;
}
.rail .tool-button, .rail #allFeatures { flex: none }
.rail .tool-caption { font-size: 11px }
.rail .all { min-height: 44px !important }
.feature-shortcuts { display: grid; gap: 5px; margin-block-end: 5px }
.feature-shortcuts button { min-height: 44px; text-align: start }
.feature-shortcuts button .ui-icon { vertical-align: middle }
.feature-category[hidden] { display: none }

main#canvasArea, body.right-overlay main#canvasArea {
  height: calc(100dvh - var(--top) - var(--bottom));
  position: relative;
}
#canvasArea > .canvas-top {
  position: absolute;
  z-index: 4;
  inset: 8px 8px auto;
  width: auto;
  min-height: 0;
  padding: 0;
  background: transparent;
  border: 0;
  pointer-events: none;
}
.canvas-top > div:not([hidden]) {
  padding: 5px 8px;
  border: 1px solid var(--a-border);
  border-radius: 8px;
  background: var(--a-surface);
  pointer-events: auto;
}
#canvasArea #status {
  position: absolute;
  width: max-content;
  max-width: min(100%, 460px);
  min-width: 0;
  max-height: none;
  margin: 0;
  overflow-wrap: anywhere;
  padding: 7px 11px;
  top: 0;
  left: 50%;
  transform: translateX(-50%);
  background: var(--a-surface);
  border: 1px solid var(--a-border);
  border-radius: 10px;
  box-shadow: var(--a-elevation);
  font-size: 12px;
  opacity: 0;
}
#canvasArea #status.visible-message { opacity: 1 }
.canvas-top:has(> div:not([hidden])) #status { top: calc(100% + 5px) }
.drawing-controls {
  position: fixed;
  z-index: 8;
  bottom: 0;
  left: var(--rail);
  right: var(--workspace);
  height: var(--bottom);
  padding: 0 8px env(safe-area-inset-bottom, 0px);
  display: flex;
  justify-content: center;
  align-items: center;
  gap: clamp(5px, 1vw, 16px);
  border-top: 1px solid var(--a-border);
  background: var(--a-surface);
}
body.right-collapsed .drawing-controls, body.right-overlay .drawing-controls { right: 0 }
.drawing-size {
  --range-step-width: 44px;
  flex: 1 1 260px;
  max-width: 440px;
  font-size: 12px;
}
.drawing-controls .ui-icon, #close .ui-icon { width: 20px; height: 20px }
.editor-popover {
  position: fixed;
  inset: auto;
  margin: 0;
  max-height: calc(100dvh - var(--top) - var(--bottom) - 12px);
  overflow: auto;
  overscroll-behavior: contain;
  padding: 10px;
  color: var(--a-text);
  background: var(--a-surface);
  border: 1px solid var(--a-border-strong);
  border-radius: var(--a-radius);
  box-shadow: var(--a-elevation);
}
.editor-popover:not(:popover-open) { display: none }
#fileActions {
  left: 9px;
  top: calc(var(--top) + 4px);
  width: min(280px, calc(100vw - 18px));
}
#fileActions:popover-open { display: grid }
#fileActions button { min-height: 44px; text-align: start }
#fileActions #saveState { font-size: 12px; padding: 4px 2px; color: var(--a-subtle) }
#viewActions {
  inset-inline-start: calc(var(--rail) + 8px);
  bottom: calc(var(--bottom) + 6px);
  width: min(430px, calc(100vw - var(--rail) - 16px));
  white-space: normal;
}
#viewActions:popover-open { display: flex; flex-wrap: wrap; justify-content: flex-start }
#viewActions button { min-height: 44px }
#viewActions button[aria-pressed="true"] { background: var(--a-accent-soft) }
#viewActions #c04ContextBar { margin: 0; width: 100%; border-top: 1px solid var(--a-border) }
body.workspace-left-handed #viewActions { inset-inline-start: auto; inset-inline-end: calc(var(--rail) + 8px) }
body.workspace-left-handed .drawing-controls { left: var(--workspace); right: var(--rail) }
body.workspace-left-handed:is(.right-collapsed, .right-overlay) .drawing-controls { left: 0; right: var(--rail) }

body.right-collapsed .right-dock { display: none }
.right-dock {
  bottom: var(--bottom);
  border-bottom: 1px solid var(--a-border);
}
aside#workspace {
  display: flex;
  flex-direction: column;
}
aside#workspace .dock-close {
  align-self: flex-end;
  flex: none;
  margin: 4px 7px 0;
  min-width: 44px;
  min-height: 44px;
  padding: 5px;
}
#workspace > .box-stack { height: auto; flex: 1; min-height: 0 }
#boxStack > .workspace-box[hidden] { display: none !important; }
#splitter { bottom: var(--bottom) }
body:has(.right-dock[data-panel]:not([data-panel=""])) #splitter { display: none }
.layer-page {
  overflow: auto;
  overscroll-behavior: contain;
}
.layer-page-head { flex-shrink: 0 }
.layer-page-actions { border: 0; padding: 8px 0 0; flex: none }
#layerPageList { flex: none; min-height: 0; max-height: 42dvh; margin-block: 10px }
.layer-details, .layer-filters { margin: 0 0 8px; width: 100% }
.layer-details > summary, .layer-filters > summary, .brush-disclosure > summary { cursor: pointer; padding: 7px 2px }
.layer-page-fields { display: grid; gap: 8px; min-width: 0 }
.layer-page-fields label { flex-wrap: wrap }
.layer-page-fields label input:not([type=checkbox]), .layer-page-fields label select { max-width: 100% }
.layer-details :is(#layerComps, #layerVectorMask) { max-height: none }
.layer-list button { min-height: 44px }
.m10-presets > label { font-size: 13px; margin-bottom: 12px }
.box-body #brush { min-height: 44px }
.brush-disclosure { margin-top: 7px }
body.illustro-focus-mode .drawing-controls,
body.illustro-focus-mode .topbar > button:not(#c04FocusQuick, #c04FocusExit) { display: none }

@media (max-width: 760px) {
  :root { --top: 52px }
  .topbar { padding-inline: 4px; gap: 0 }
  .topbar button { padding-inline: 5px }
  .topbar #qaEntry { min-width: 34px }
  body:not(.workspace-left-handed) .drawing-controls { right: 0 }
  body.workspace-left-handed .drawing-controls { left: 0; right: var(--rail) }
  .right-dock, body.right-overlay .right-dock { bottom: var(--bottom); height: min(55dvh, 610px) }
  #layerPageList { max-height: min(29dvh, 255px) }
}
@media (max-width: 540px) {
  .drawing-controls button span { display: none }
  .drawing-size { gap: 4px }
}
@media (max-width: 360px) {
  .topbar button { min-width: 42px }
  .drawing-controls { padding-inline: 4px; gap: 3px }
}

#fileActionsOpen[data-storage-error] {
  color: #9d3030;
  border-color: currentColor;
}
#fileActionsOpen[data-storage-error]::after {
  content: "!";
  font-weight: 800;
}
@media (max-width: 760px) {
  .topbar button, .drawing-controls button { flex-direction: column; gap: 1px }
  .topbar button span, .drawing-controls button span { display: block; font-size: 9px; line-height: 11px }
  .topbar button .ui-icon { width: 20px; height: 20px }
  .topbar button .current-color { width: 20px; height: 20px }
}

:root { --dock-tabs: 46px; --bottom: calc(73px + env(safe-area-inset-bottom, 0px)); }
#rightDock { flex-direction: row; background: var(--a-surface); }
#rightDock .workspace-tabs {
  display: flex;
  flex-direction: column;
  flex: 0 0 var(--dock-tabs);
  width: var(--dock-tabs);
  overflow-y: auto;
  overscroll-behavior: contain;
  border-inline-end: 1px solid var(--a-border);
}
.workspace-tabs button {
  display: grid;
  place-items: center;
  width: 100%;
  min-height: 43px;
  padding: 3px;
  border: 0;
  border-inline-start: 3px solid transparent;
  border-radius: 0;
  background: transparent;
}
.workspace-tabs button[aria-pressed=true],
.workspace-tabs :is(#colorPage,#brushPage)[aria-expanded=true] {
  border-inline-start-color: var(--a-focus);
  background: var(--a-accent-soft);
}
.workspace-tabs .workspace-paint-tabs { margin-block-start: auto; padding-block: 4px }
.workspace-tabs .current-color { width: 20px; height: 20px }
#rightDock > #workspace, #rightDock > #layerPage { flex: 1; width: auto; min-width: 0 }

#workspace .workspace-box { border: 0; border-bottom: 1px solid var(--a-border); border-radius: 0; box-shadow: none; margin: 0 }
#workspace .box-stack { touch-action: pan-y; overscroll-behavior: contain }
#workspace :is(input[type=text],input[type=search],input[type=number]) { border-radius: 0; border-width: 0 0 1px }
body:has(#rightDock[data-panel]:not([data-panel=""])) #splitter { display: flex }
body.right-collapsed #splitter { display: none !important }
#dockCompactToggle { display: none }
.fixed-workspace-actions {
  position: fixed;
  z-index: 9;
  inset: auto 0 0 auto;
  min-width: 225px;
  width: var(--workspace);
  height: var(--bottom);
  display: flex;
  align-items: center;
  justify-content: center;
  padding-bottom: env(safe-area-inset-bottom, 0px);
  border-top: 1px solid var(--a-border);
  background: var(--a-surface);
}
.fixed-workspace-actions button { min-width: 43px; min-height: 44px; padding: 4px; border: 0; background: transparent }
.fixed-workspace-actions button[aria-expanded=true], .fixed-workspace-actions button[aria-pressed=true] { background: var(--a-accent-soft) }
.fixed-workspace-actions button span { display: none }
body.workspace-left-handed .fixed-workspace-actions { inset-inline: 0 auto }
body:is(.right-collapsed,.right-overlay) .fixed-workspace-actions { width: 225px }
body:is(.right-collapsed,.right-overlay):not(.workspace-left-handed) .drawing-controls { right: 225px }
body:is(.right-collapsed,.right-overlay).workspace-left-handed .drawing-controls { left: 225px }
body.illustro-focus-mode .fixed-workspace-actions { display: none }
@media (min-width: 761px) {
  body.right-collapsed #rightDock { display: flex; width: var(--dock-tabs); top: var(--top); bottom: var(--bottom); height: auto }
  body.right-collapsed:not(.workspace-left-handed) main#canvasArea { margin-right: var(--dock-tabs) }
  body.right-collapsed.workspace-left-handed main#canvasArea { margin-left: var(--dock-tabs) }
}
@media (max-width: 760px) {
  #dockCompactToggle { display: inline-flex }
  body:has(#rightDock[data-panel]) #splitter { display: none }
  .fixed-workspace-actions { width: 225px }
  body:not(.workspace-left-handed) .drawing-controls { right: 225px }
  body.workspace-left-handed .drawing-controls { left: 225px }
}
@media (max-width: 570px) {
  :root { --bottom: calc(116px + env(safe-area-inset-bottom, 0px)); }
  .fixed-workspace-actions, body:is(.right-collapsed,.right-overlay) .fixed-workspace-actions {
    inset-inline: 0;
    width: 100%;
    height: calc(43px + env(safe-area-inset-bottom, 0px));
  }
  body:is(.right-collapsed,.right-overlay):not(.workspace-left-handed) .drawing-controls,
  body:not(.workspace-left-handed) .drawing-controls { right: 0 }
  body:is(.right-collapsed,.right-overlay).workspace-left-handed .drawing-controls,
  body.workspace-left-handed .drawing-controls { left: 0 }
  .drawing-controls { bottom: calc(43px + env(safe-area-inset-bottom, 0px)); height: 73px; padding-bottom: 0 }
}

/* The list gets the panel height. Secondary actions open over the list. */
#layerPage { overflow: hidden; }
#layerPageList { flex: 1; max-height: none; margin-block: 6px; }
.layer-page-head { padding: 0 0 6px; }
.layer-page-head h2 { margin: 0; }
.layer-toolbar { display: flex; gap: 2px; }
.layer-toolbar button, .layer-entry :is(.layer-visibility,.layer-grip), .layer-group-row .layer-visibility,
.layer-folder-actions > summary {
  display: inline-grid;
  place-items: center;
  width: 44px;
  min-height: 44px;
  padding: 0;
}
#addLayerPage { color: var(--a-focus); background: var(--a-accent-soft); }
.layer-properties {
  display: grid;
  grid-template-columns: minmax(0, 3fr) minmax(0, 2fr);
  gap: 8px;
  align-items: center;
  flex: none;
  padding: 6px 0;
}
.layer-properties > .workspace-range { margin: 0; font-size: 11px; }
#layerBlendMode { max-width: 55%; min-height: 44px; white-space: normal; }
.layer-batch-summary { padding: 6px 4px; }
.layer-actions-menu { position: fixed; inset: auto; margin: 0; padding: 12px; overflow: auto; overscroll-behavior: contain; }
.layer-actions-menu button { min-height: 40px; }
.layer-actions-menu .layer-page-meta { padding-top: 0; overflow-wrap: anywhere; }
.layer-actions-menu .layer-mode-actions { margin-block: 8px; }
#deleteLayer { color: #a03434; }

#layerPageList .layer-entry, #layerList .layer-entry { grid-template-columns: auto minmax(0,1fr) auto; gap: 2px; align-items: center; }
#layerList .layer-entry-compact { grid-template-columns: auto minmax(0,1fr) auto auto; }
.layer-entry .layer-row { display: flex; gap: 7px; align-items: center; min-width: 0; padding: 3px 6px; min-height: 48px; }
.layer-description { display: flex; align-items: center; gap: 4px; min-width: 0; }
.layer-description .layer-name { overflow: hidden; white-space: nowrap; text-overflow: ellipsis; }
.layer-lock-indicator { display: inline-grid; flex-shrink: 0; }
.layer-lock-indicator .ui-icon { width: 15px; height: 15px; }
.layer-visibility, .layer-grip { border-color: transparent; background: transparent; }
.layer-grip { touch-action: none; cursor: grab; }
.layer-grip:active { cursor: grabbing; }
.layer-grip:disabled { visibility: hidden; }
.layer-dragging .layer-row { opacity: .65; }
.layer-edit-shortcuts { grid-column: 2 / -1; display: flex; flex-wrap: wrap; gap: 3px; }
.layer-edit-shortcuts button { font-size: 11px; padding-inline: 5px; }
.layer-preview {
  display: block;
  position: relative;
  flex-shrink: 0;
  width: 38px;
  height: 38px;
  border-radius: 5px;
  overflow: hidden;
  border: 1px solid var(--a-border-strong);
  background: conic-gradient(#d7dce5 25%, #f8faff 0 50%, #d7dce5 0 75%, #f8faff 0) 0 0 / 10px 10px;
}
.layer-preview canvas { display: block; width: 100%; height: 100%; background: transparent; border-radius: 0; }
.layer-preview-position { position: absolute; right: 1px; bottom: 1px; width: 13px; height: 10px; border-radius: 2px; border: 1px solid #61739c; background: #fffe; }
.layer-preview-position i { position: absolute; width: 4px; height: 4px; border-radius: 50%; background: #324aa2; transform: translate(-50%,-50%); }
.layer-group-row .layer-folder-toggle { display: flex; align-items: center; gap: 5px; }
.layer-folder-icons { display: inline-flex; flex: none; align-items: center; }
.layer-folder-icons .ui-icon { width: 18px; height: 18px; }
.layer-folder-toggle[aria-expanded=false] .layer-folder-icons .ui-icon:last-child { transform: rotate(-90deg); }
.layer-folder-actions { display: contents; }
.layer-folder-actions > summary { cursor: pointer; list-style: none; border-radius: 8px; }
.layer-folder-actions > summary::-webkit-details-marker { display: none; }
.layer-folder-actions > div { width: 100%; display: flex; flex-wrap: wrap; gap: 4px; }
.layer-folder-actions:not([open]) > div { display: none; }

.brush-size-preview { position: absolute; inset: 0; z-index: 4; pointer-events: none; }
.brush-size-preview i {
  position: absolute;
  left: 50%;
  top: 43%;
  transform: translate(-50%,-50%);
  border: 1px solid #202a42;
  box-shadow: 0 0 0 1px #fff;
  box-sizing: border-box;
  border-radius: 50%;
}
.brush-size-preview output {
  position: absolute;
  left: 50%;
  top: 5%;
  transform: translateX(-50%);
  padding: 4px 9px;
  color: var(--a-text);
  background: var(--a-surface);
  border: 1px solid var(--a-border-strong);
  border-radius: 6px;
  font-variant-numeric: tabular-nums;
}

.brush-catalog { display: grid; gap: 2px; max-height: 37dvh; overflow-y: auto; overscroll-behavior: contain; touch-action: pan-y; }
.brush-catalog button {
  display: grid;
  grid-template-columns: minmax(60px, .9fr) minmax(0, 1fr);
  gap: 6px;
  align-items: center;
  text-align: start;
  min-height: 44px;
  padding: 2px 5px;
  border: 0;
  border-bottom: 1px solid var(--a-border);
  border-inline-start: 3px solid transparent;
  border-radius: 0;
  background: transparent;
}
.brush-catalog button[aria-pressed=true] { border-inline-start-color: var(--a-focus); background: var(--a-accent-soft) }
.brush-catalog canvas { width: 100%; aspect-ratio: 116 / 36; height: auto; background: transparent; touch-action: pan-y }
.brush-catalog span { overflow: hidden; text-overflow: ellipsis }
.brush-detail-open { width: 100%; margin-block: 6px; min-height: 42px }
.workspace-details-pane {
  flex: 0 0 min(290px, 32vw);
  min-width: 0;
  display: flex;
  flex-direction: column;
  border-inline-start: 1px solid var(--a-border);
  background: var(--a-surface);
}
.workspace-details-pane[hidden] { display: none }
.workspace-details-pane header { display: flex; align-items: center; gap: 6px; border-bottom: 1px solid var(--a-border) }
.workspace-details-pane header button { min-width: 44px; min-height: 44px; border: 0; background: transparent }
.workspace-details-body { min-height: 0; overflow: auto; overscroll-behavior: contain; padding: 5px 7px }
#rightDock.with-workspace-details { width: min(calc(var(--workspace) + 290px), calc(100vw - var(--rail))) }
#rightDock.with-workspace-details #workspace { flex: 1 }
@media (min-width: 761px) {
  body:has(#rightDock.with-workspace-details) #splitter { right: min(calc(var(--workspace) + 290px), calc(100vw - var(--rail))) }
}
@media (max-width: 760px) {
  #rightDock.with-workspace-details { width: auto }
  .workspace-details-pane { flex-basis: 43% }
}
.layer-properties { border-top: 1px solid var(--a-border) }
@media (prefers-reduced-motion: no-preference) {
  .layer-drop-target { transition: background-color .12s ease-out, box-shadow .12s ease-out }
  .workspace-tabs button { transition: background-color .12s ease-out }
}
#documentBoxBody[data-active-tool-panel] > :not([data-tool-panel]) { display:none }
#documentBoxBody[data-active-tool-panel="selection"] > [data-tool-panel]:not([data-tool-panel="selection"]),
#documentBoxBody[data-active-tool-panel="transform"] > [data-tool-panel]:not([data-tool-panel="transform"]),
#documentBoxBody[data-active-tool-panel="smartFill"] > [data-tool-panel]:not([data-tool-panel="smartFill"]),
#documentBoxBody[data-active-tool-panel="shapes"] > [data-tool-panel]:not([data-tool-panel="shapes"]),
#documentBoxBody[data-active-tool-panel="rulers"] > [data-tool-panel]:not([data-tool-panel="rulers"]),
#documentBoxBody[data-active-tool-panel="smudge"] > [data-tool-panel]:not([data-tool-panel="smudge"]) { display:none }

#layerPageList .layer-entry, #layerList .layer-entry {
  grid-template-columns: 38px 44px minmax(0,1fr) 36px 38px;
  background: transparent;
  border: 0;
  border-bottom: 1px solid var(--a-border);
  border-radius: 0;
}
#layerPageList .layer-entry:has(.layer-row[aria-pressed=true]), #layerList .layer-entry:has(.layer-row[aria-pressed=true]) {
  background: var(--a-accent-soft);
  box-shadow: inset 3px 0 var(--a-focus);
}
.layer-entry .layer-row { padding: 1px; border: 0; background: transparent; }
.layer-entry :is(.layer-lock,.layer-grip,.layer-visibility) { width:100%; min-width:0; background: transparent; border:0 }
.layer-entry .layer-lock[aria-pressed=false] { color: var(--a-subtle); opacity:.55 }
.layer-entry .layer-inline-name {
  min-width:0;
  width:100%;
  min-height:44px;
  padding-inline:3px;
  text-align:start;
  border:0;
  background:transparent;
}
.layer-entry input.layer-inline-name { border-bottom:1px solid var(--a-focus) }
.layer-entry .layer-lock-indicator { display:none }
.layer-blend-fields { display: flex; min-width:0; align-items: center; gap:2px }
.layer-blend-fields .workspace-choice { width:100%; min-width:0 }
.layer-blend-fields #layerBlendMode { min-width:37px; padding-inline:2px; background:transparent; border:0 }

#workspace .workspace-box:has(#documentBoxBody[data-active-tool-panel]) > .box-heading { display: none }
#workspace #documentBoxBody > details { border: 0; border-top: 1px solid var(--a-border); border-radius: 0; margin: 3px 0 }

ui/aurora.css:
/*
 * Illustro Aurora — approved narrow-hue visual direction.
 * Blue -> periwinkle -> violet with a small violet-pink edge.
 * Source: docs/ui/UI_THEME_CANDIDATES_2026-09-30.md §10–11.
 * Keep paper, Boxes and control bodies neutral; display aurora light only
 * near brand, selection, active indicator, focus and primary Box edges.
 */
:root{
 --a-background:#F7F9FC;
 --a-surround:#E9EEF5;
 --a-canvas-surround:#F1F4F9; /* Matches GPU viewport outside the document. */
 --a-surface:#FFFFFF;
 --a-surface-soft:#F9FBFF;
 --a-border:#E2E7F0;
 --a-border-strong:#CED8E7;
 --a-text:#222C40;
 --a-subtle:#5C6C83;
 --a-accent:#718DFA;
 --a-accent-soft:#E9EEFF;
 --a-focus:#5865CC;
 --a-elevation:0 5px 22px #304F8520;
 --aurora-blue:#5EA8FF;
 --aurora-periwinkle:#708FFF;
 --aurora-violet:#8B7CFF;
 --aurora-pink:#C681DE;
 --aurora-flow:linear-gradient(112deg,var(--aurora-blue),var(--aurora-periwinkle) 36%,var(--aurora-violet) 76%,var(--aurora-pink));
 --aurora-selection:linear-gradient(125deg,#EDF6FF,#F3F0FF);
 --aurora-edge:linear-gradient(100deg,#75B8FF,#8996FF 58%,#AB91EF);
 --a-radius:13px;
}
body{color:var(--a-text);background:var(--a-surround)}
.topbar{background:#FFFFFFF7;border-color:var(--a-border);box-shadow:0 2px 8px #4C62810D}
.brand-mark{flex-basis:32px;width:32px;height:32px;border:1px solid #DDE5FA;background:#fff;border-radius:10px;box-shadow:0 2px 7px #779BDD1E}
.brand-artwork{display:block;width:100%;height:100%;object-fit:contain;object-position:center;border-radius:inherit}
.topbar .brand strong{font-weight:750;letter-spacing:-.55px}
.brand-sub{color:#758399}
.topbar #save{background:var(--aurora-selection);border-color:#CBDAF8}
html[data-ui-input="hover"] .topbar #save:hover:not(:disabled){background:#E1EAFF;border-color:#9AB5F5}
.topbar #save:disabled{background:#F4F6FA}
.topbar #saveState{color:var(--a-subtle)}
.rail{background:#FEFFFF;border-color:var(--a-border)}
.rail .tool-button,.rail #allFeatures{color:#4B5975}
html[data-ui-input="hover"] .rail .tool-button:hover:not(:disabled),html[data-ui-input="hover"] .rail #allFeatures:hover{background:#F0F5FF;border-color:#DFE6FB}
.rail .tool-button[aria-pressed=true]{
 background:var(--aurora-selection);
 border-color:#B8CAFC;
 box-shadow:inset 3px 0 #7A91FF,0 1px 5px #6988EF15;
 color:#364CA9;
}
.rail .tool-button[aria-pressed=true] .tool-caption{color:#364CA9;font-weight:720}
.rail .tool-caption{color:#66758D}
.rail .all{border-top:1px solid var(--a-border)!important;color:#536BA5}
.rail .tool-button:disabled{opacity:.78}
/* Stationary surroundings must not change when a frame is missing or moving. */
main#canvasArea{background:var(--a-canvas-surround)}
.canvas-top{background:#FFFFFFDF;border-color:var(--a-border)}
#status{color:var(--a-subtle)}
.document-actions button{border-color:#DCE3EF;color:#485A75;background:#FFFFFF}
html[data-ui-input="hover"] .document-actions button:hover:not(:disabled){background:#EFF4FF}
#new{background:var(--aurora-selection);border-color:#BFD4F8;color:#4053A0}
html[data-ui-input="hover"] #new:hover{background:#E2EDFF}
.surface{border-color:#CAD4E2;box-shadow:0 10px 27px #3E54792B,0 2px 7px #445C7413}
.right-dock{background:#F8FAFF;border-color:#DEE5F0}
.box-stack{scrollbar-color:#D1DCF1 transparent}
.workspace-box{background:#FFFFFF;border:1px solid #E0E6F1;box-shadow:0 2px 7px #385A820A;border-radius:var(--a-radius)}
.workspace-box[data-box-id="right.layers"]:before,
.workspace-box[data-box-id="right.color"]:before,
.workspace-box[data-box-id="right.brush"]:before{
 content:"";display:block;height:2px;background:var(--aurora-edge);opacity:.83
}
.box-heading{color:#36425B}
.box-toggle{color:#6076A6}
html[data-ui-input="hover"] .box-toggle:hover:not(:disabled){background:#EDF2FF;color:#3D55A4}
.box-title{color:#36425B}
.box-toggle:focus-visible{outline:2px solid var(--a-focus);outline-offset:-3px}
.workspace-box:focus-visible{outline:2px solid #AEC3FC;outline-offset:2px}
.box-glyph{display:grid;place-items:center;color:#687DA8;flex:none}
.box-glyph .ui-icon{width:17px;height:17px}
.workspace-box:has(.box-toggle[aria-expanded=true]) .box-glyph{color:#6278CE}
.box-summary{color:#65758E}
.box-more{color:#677896}
.box-body{border-top-color:#EFF2FA}
.box-more-menu{background:#F9FBFF;border-color:var(--a-border)}
.scalar-row input[type=number],.box-body #brush{border-color:#D2DBEA;color:var(--a-text);background:#fff}
input[type=range]{accent-color:#748BEE}
input[type=checkbox]{accent-color:#748BEE}
.unavailable{border-color:#D8DFEF;color:#64738D;background:#FBFCFF}
.layer-row{border-color:#E2E7F0;color:#40506A}
.layer-row[aria-pressed=true]{background:var(--aurora-selection);border-color:#B5C7F6;border-left-color:#6F89F3}
.layer-state{color:#435BBC}
.commands{border-color:#DEE5F0;background:#FFFFFF}
.commands button{color:#4A5D7F}
html[data-ui-input="hover"] .commands button:hover:not(:disabled){background:#EFF3FF}
.commands button.selected,.commands button[aria-expanded=true]{color:#354DAC;background:var(--aurora-selection)}
#splitter:before{background:#C3D2E9}
.resize-grip{color:#7386AB;background:#FAFBFF;border-color:#C9D5E9}
html[data-ui-input="hover"] #splitter:hover,#splitter.dragging{background:#A2B8F42B}
.layer-page{background:#F9FAFF}
.layer-page-head{border-color:#DCE5F0}
.layer-page-head small{color:#697CB0}
.layer-page-list .layer-row[aria-pressed=true]{box-shadow:0 1px 4px #788FEA20}
.layer-page-actions{border-color:#DBE3F2}
.layer-page-actions button{background:var(--aurora-selection);border-color:#BBCCF3;color:#4355A5}
.features-panel{background:#FFFFFF;border-color:#DDE5F2;box-shadow:0 13px 34px #3A5A9831}
.feature-category{display:flex;justify-content:flex-start;gap:10px;border-color:#E6EBF4}
.feature-category .ui-icon{flex:none;width:18px;height:18px;color:#6B7FAD}
.feature-category .feature-label{flex:1;text-align:left}
.feature-chevron .ui-icon{width:13px;height:13px;transform:rotate(-90deg)}
.feature-category[data-group-start=true]{border-top-color:#E2E8F5}
html[data-ui-input="hover"] .feature-category:hover{background:var(--aurora-selection)}
/* The icon does not change dimensions between active, disabled and hover states. */
.ui-icon{display:inline-block;flex:none;vertical-align:middle;width:22px;height:22px;pointer-events:none}
.tool-glyph{display:grid;place-items:center;min-width:26px;min-height:26px}
.tool-glyph .ui-icon{width:23px;height:23px}
.rail #allFeatures>.ui-icon{width:22px;height:22px;margin-bottom:3px;color:#6277BE}
.chevron .ui-icon{width:15px;height:15px}
.box-more .ui-icon{width:17px;height:17px}
.topbar button{display:inline-flex;align-items:center;gap:6px;justify-content:center}
.topbar button .ui-icon{width:18px;height:18px}
.commands button .ui-icon{width:22px;height:22px}
.document-actions button,.box-actions button,.layer-page-actions button,#addLayer,#featuresBack{
 display:inline-flex;align-items:center;justify-content:center;gap:5px
}
.document-actions .ui-icon,.box-actions .ui-icon,#addLayer .ui-icon,.layer-page-actions .ui-icon,#featuresBack .ui-icon{width:16px;height:16px}
#featuresClose,#closeLayerPage{display:grid;place-items:center}
#featuresClose .ui-icon,#closeLayerPage .ui-icon{width:18px;height:18px}
.bottom button{display:flex;align-items:center;justify-content:center;gap:3px}
.bottom .ui-icon{width:17px;height:17px}
/* QA placement + skin: the closed sheet has no invisible hit area. */
.qa-review{
 position:fixed;left:auto;top:auto;right:calc(var(--workspace) + 12px);bottom:14px;
 width:min(356px,calc(100vw - var(--rail) - var(--workspace) - 26px));
 max-width:calc(100vw - var(--rail) - 22px);max-height:min(62dvh,520px);
 background:#FFFFFFF7;border:1px solid #BACCF7;
 box-shadow:0 11px 32px #334E8A38;
 padding:0;border-radius:15px;overflow:auto;
}
body.right-collapsed .qa-review{right:18px}
@media(min-width:761px){body.right-overlay .qa-review{right:calc(var(--workspace) + 12px)}}
@media(max-width:760px){
 .qa-review{
  left:auto;top:auto;right:9px;
  bottom:calc(var(--bottom) + env(safe-area-inset-bottom) + 10px);
  width:min(318px,calc(100vw - var(--rail) - 18px));
  max-height:min(61dvh,480px);
 }
}
@media(max-height:640px){
 .qa-review{max-height:min(61dvh,calc(100dvh - var(--top) - var(--bottom) - 110px))}
}
.qa-review>summary{
 display:flex;align-items:center;gap:9px;
 background:var(--aurora-selection);
 color:#354AA2;
 font-weight:740;
 font-size:13px;
 padding:12px 13px;
 cursor:pointer;
 list-style:none;
 position:sticky;top:0;z-index:1;
 border-bottom:1px solid #D5DEF6;
}
.qa-review>summary::-webkit-details-marker{display:none}
.qa-review>summary .ui-icon{width:19px;height:19px}
.qa-summary-hint{margin-left:auto;font-size:10px;font-weight:530;color:#6378AD}
.qa-review:not([open]){max-height:45px;width:max-content;max-width:calc(100vw - var(--rail) - 20px)}
.qa-review .qa-panel{margin:0;border:0;background:transparent;padding:12px 14px 16px}
.qa-review .qa-panel>summary{font-size:12px;padding:4px 0;color:#3A4E8F}
.qa-review .qa-panel ol{padding-left:20px;font-size:12px;line-height:1.55}
.qa-review .qa-panel li{margin:0 0 6px}
.qa-review .qa-panel select{min-height:36px;border:1px solid #CCD7EC;border-radius:8px}
.qa-review .qa-panel #qaCopy{background:var(--aurora-selection);border-color:#BBCBF5}
.qa-review .qa-auto{background:#F6F9FE}
@media(max-width:760px){
  .qa-review{border-radius:11px}
  .qa-review>summary{padding:9px 10px;font-size:12px}
  .qa-summary-hint{font-size:9px}
  .tool-glyph .ui-icon{width:19px;height:19px}
  .topbar button{gap:2px}
  .topbar .ui-icon{width:19px;height:19px}
}
@media(prefers-reduced-motion:reduce){
 .ui-icon,.brand-artwork{transition:none}
}

/* Align the remaining M06 export dialog and Compact toolbar with Aurora. */
.export-dialog{background:#FFFFFF;border:1px solid #CFDAED;color:var(--a-text);box-shadow:0 17px 55px #25385E48}
.export-dialog #exportTransparencyInfo{background:#EEF3FF;color:#465D90}
.export-dialog #exportRun{background:var(--aurora-selection);border-color:#B7C9F5;color:#374EA0}
html[data-ui-input="hover"] .export-dialog #exportRun:hover:not(:disabled){background:#DDE9FF}
.bottom{background:#F8FAFF;border-top:1px solid #DAE3F3}
.bottom button{color:#4B5F8C}
.resize-grip{
 background-color:#FAFBFF;
 background-image:radial-gradient(circle,#8195C4 1.2px,transparent 1.5px);
 background-size:6px 8px;
 background-repeat:repeat-y;
 background-position:center center;
}

/* QA has its own permanent topbar entry: hiding the floating card never
   removes access to the checklist, and never steals drawing/Export clicks. */
.topbar #qaEntry{color:#3E51A6;background:var(--aurora-selection);border:1px solid #C7D4FC;border-radius:10px;font-weight:730}
html[data-ui-input="hover"] .topbar #qaEntry:hover{background:#E0E9FF;border-color:#AABBF1}
.topbar #qaEntry[aria-expanded=true]{box-shadow:inset 0 -2px #8396F2}
.qa-review:not([open]),.qa-review:has(#qaPanel:not([open])){display:none!important}
@media(max-width:760px){
 .topbar #qaEntry span{display:inline;font-size:10px}
 .topbar #qaEntry{padding:3px 5px;min-height:30px}
 .topbar #qaEntry .ui-icon{width:16px;height:16px}
}

/* M07 visual repair: a single source of truth for ALL pointer states,
   not only default backgrounds. No legacy yellow hover / pressed overlay. */
html[data-ui-input="hover"] button:hover:not(:disabled){background-color:#EFF3FF;border-color:#C5D3F6}
button:active:not(:disabled){
 background:#E3EAFF;border-color:#A6B8F1;color:#30498C;
 box-shadow:inset 0 1px 2px #536CA51C;
}
button:disabled{color:var(--a-subtle);background-color:#F5F7FC}
.rail .tool-button:active:not(:disabled),
.rail #allFeatures:active:not(:disabled),
.feature-category:active:not(:disabled),
.commands button:active:not(:disabled),
.box-toggle:active:not(:disabled),
.box-more:active:not(:disabled),
.bottom button:active:not(:disabled){background:var(--aurora-selection);color:#3852A6;border-color:#A6B8F1}
.rail .tool-button[aria-pressed=true]:active:not(:disabled){background:var(--aurora-selection)}
.topbar #qaEntry:active:not(:disabled),#new:active:not(:disabled),
.export-dialog #exportRun:active:not(:disabled){background:var(--aurora-selection);border-color:#9EADF1}
.feature-category:focus-visible,.features-header button:focus-visible{outline-offset:-2px}
.features-panel{
 padding:11px 12px;border-radius:13px;
 background:#FFFFFFF9;
 box-shadow:0 14px 34px #314B8940,0 2px 6px #405C8B12;
}
.features-header{
 position:sticky;top:-11px;z-index:1;
 background:#FFFFFFF4;border-bottom:1px solid #E6ECF8;
 margin:-1px -2px 7px;padding:4px 5px 10px;
}
.feature-category{min-height:41px;border-radius:8px}
.feature-categories{gap:3px}
.feature-actions{min-height:0}
.feature-actions h3{margin:8px 0;font-weight:700}
.feature-actions button{border-color:#E3E9F4;background:#FFFFFF}
html[data-ui-input="hover"] .feature-actions button:hover:not(:disabled){background:var(--aurora-selection)}


/* M08: full drawing viewport. The paper bounds are drawn in GPU view space;
   a fixed CSS paper rectangle would stay white when the document moves. */
body.canvas-viewport main#canvasArea{overflow:hidden}
body.canvas-viewport main#canvasArea>.canvas-top,
body.canvas-viewport main#canvasArea>.canvas-view-strip{flex:0 0 auto}
body.canvas-viewport main#canvasArea>.surface{
 display:block;flex:1 1 0;align-self:stretch;min-width:0;min-height:0;
 width:100%;max-width:none;height:auto;margin:0;padding:0;
 background:var(--a-canvas-surround);border:0;border-radius:0;box-shadow:none;overflow:hidden;
}
/* Drawing frames, the retained artwork and exposed scene use the same
   stationary fallback; only the artwork itself moves. */
body.canvas-viewport main#canvasArea>.surface>.illustro-viewport-scene{
 background:var(--a-canvas-surround);
}
body.canvas-viewport main#canvasArea>.surface>.illustro-viewport-scene>#canvas{
 display:block;width:100%;height:100%;max-width:none;aspect-ratio:auto;
 background:var(--a-canvas-surround);touch-action:none;
}
/* Header flex buttons must still honor the saved/error visibility state. */
#retryWorkSave[hidden]{display:none!important}

ui/shell.css:
/* M07 Aurora design tokens — presentation only; renderer ownership remains in canvas. */
:root{
  --a-surface:#fff;--a-surface-soft:#fffdf9;--a-background:#f5f4f1;
  --a-border:#e8e3d9;--a-border-strong:#d9c8aa;--a-text:#2d2b28;
  --a-subtle:#666258;--a-accent:#dda048;--a-accent-soft:#fff0d4;--a-focus:#85501c;
  --a-elevation:0 4px 19px #272f2b16;--a-radius:12px;
  --a-space:8px;--a-box-header:40px;--a-strip:52px;--a-target:40px;
  --rail:68px;--top:56px;--bottom:52px;--workspace:344px;
  font-family:Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif;
  color:var(--a-text);background:var(--a-background);
}
body{overflow:hidden;background:var(--a-background)}
button{transition:background-color .12s,border-color .12s;color:var(--a-text);border-color:var(--a-border)}
html[data-ui-input="hover"] button:hover:not(:disabled){background:var(--a-accent-soft);border-color:var(--a-border-strong)}
button:active:not(:disabled){background:var(--a-accent-soft)}
button:disabled{opacity:.62;cursor:not-allowed;color:var(--a-subtle)}
button:focus-visible,input:focus-visible,summary:focus-visible,select:focus-visible{outline:3px solid var(--a-focus);outline-offset:2px}
.topbar{position:fixed;inset:0 0 auto 0;z-index:12;height:var(--top);padding:0 16px;display:flex;align-items:center;gap:9px;background:var(--a-surface);border-bottom:1px solid var(--a-border)}
.topbar .brand{display:flex;align-items:center;gap:6px;margin-right:19px}
.brand-mark{display:block;flex:0 0 30px;background:#fff;overflow:hidden;border:1px solid var(--a-border-strong);border-radius:11px;width:30px;height:30px}
.brand-artwork{display:block;width:100%;height:100%;object-fit:contain;object-position:center;border-radius:inherit}
.brand strong{font-size:17px;letter-spacing:-.7px}
.brand-sub{font-size:10px;color:#96968b;margin-left:5px;white-space:nowrap}
.topbar button{font-size:12px;border-color:transparent;background:transparent;min-height:36px;padding:5px 11px;font-weight:600}
.topbar #save{background:var(--a-accent-soft);border:1px solid var(--a-border-strong)}
.top-spacer{flex:1}
.topbar #saveState{font-size:11px;font-weight:500;color:var(--a-subtle);margin:0;white-space:nowrap}
.rail{position:fixed;left:0;top:var(--top);bottom:0;width:var(--rail);background:var(--a-surface);z-index:8;padding:10px 7px 7px;display:flex;flex-direction:column;gap:4px;overflow:hidden;border-right:1px solid var(--a-border)}
.rail .tool-button,.rail #allFeatures{min-height:51px;width:100%;border:1px solid transparent;background:transparent;border-radius:10px;display:flex;align-items:center;justify-content:center;flex-direction:column;gap:2px;padding:5px 1px}
.rail .tool-button[aria-pressed=true]{background:var(--a-accent-soft);border-color:var(--a-border-strong);box-shadow:inset 3px 0 var(--a-accent)}
.rail .tool-glyph{font-size:23px;line-height:26px;font-weight:400}
.rail .tool-caption{font-size:9px;letter-spacing:-.2px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:100%;color:var(--a-subtle)}
.rail .all-caption{display:flex;flex-direction:column;align-items:center;gap:0;line-height:10px;white-space:nowrap;text-overflow:clip;overflow:visible}
.rail .all-caption span{display:block;white-space:nowrap}
.rail .all{margin-top:auto !important;min-height:59px!important;border-top:1px solid var(--a-border)!important;border-radius:9px!important;color:var(--a-focus)}
.rail .all>span:first-child{font-size:22px}
.rail .tool-button:disabled{opacity:.43}
main#canvasArea{margin:var(--top) var(--workspace) 0 var(--rail);height:calc(100dvh - var(--top));min-height:0;overflow:auto;padding:0;display:flex;flex-direction:column;align-items:center;background:radial-gradient(circle at 50% 32%,#f1f0ed,#e3e3e1 80%)}
.canvas-top{display:flex;align-items:center;gap:16px;flex-wrap:wrap;width:100%;min-height:58px;padding:8px 20px;background:#ffffffc9;border-bottom:1px solid var(--a-border)}
#status{font-size:11px;line-height:1.35;margin:0;min-width:170px;flex:1;color:var(--a-subtle)}
.document-actions{display:flex;gap:5px;align-items:center;flex-wrap:wrap}
.document-actions button{font-size:11px;min-height:33px;padding:6px 10px;border-radius:8px}
#new{background:var(--a-accent-soft)}
.surface{flex:none;margin:auto;max-width:calc(100% - 40px);width:min(67vw,860px);min-width:0;background:#fff;border:1px solid var(--a-border-strong);box-shadow:0 8px 25px #3a464122,0 1px 4px #3a46411e}
canvas{display:block;aspect-ratio:4/3;width:100%;height:auto;touch-action:none;background:#fff}
/*
 * M07 touch selection policy
 * Android Chromium can show the OS copy/select blue highlight on what should
 * be pure application chrome. Suppress text selection/callouts ONLY for
 * non-editable controls and labels; retain real selection/copy in text inputs.
 * Do not block contextmenu globally or cancel native pointer/touch events.
 */
button,summary,[role=button],
.topbar,.rail,.commands,.bottom,.box-heading,.box-title,.box-summary,
.box-more-menu,.features-panel,.feature-category,.document-actions,
.layer-page-head,.layer-page-meta,.layer-page-actions,.box-actions,
.box-body label,.box-body .unavailable,.width-control,.resize-grip,canvas{
 -webkit-user-select:none;
 user-select:none;
 -webkit-touch-callout:none;
 -webkit-tap-highlight-color:transparent;
}
:where(input,textarea,select,[contenteditable="true"],[contenteditable=""]){
 -webkit-user-select:text;
 user-select:text;
 -webkit-touch-callout:default;
}
/* Keep editable controls and accessibility focus feedback intact. A tap is
 * still visibly acknowledged by Aurora :active, and keyboard :focus-visible. */

.right-dock{position:fixed;right:0;top:var(--top);bottom:0;width:var(--workspace);background:var(--a-surface-soft);border-left:1px solid var(--a-border);z-index:7;display:flex;flex-direction:column;min-width:0}
aside#workspace{position:relative;inset:auto;width:100%;height:auto;min-width:0;max-width:none;flex:1;min-height:0;border:0;background:transparent;padding:0;overflow:hidden;opacity:1;pointer-events:auto;transform:none;will-change:auto;contain:none}
.box-stack{height:100%;overflow-y:auto;overflow-x:hidden;overscroll-behavior:contain;padding:10px 9px 14px;scrollbar-width:thin;scrollbar-color:var(--a-border-strong) transparent}
.workspace-box{position:relative;background:var(--a-surface);border:1px solid var(--a-border);border-radius:var(--a-radius);margin-bottom:8px;box-shadow:0 1px 3px #2f3b300a;overflow:visible}
.workspace-box:has(.box-more-menu:not([hidden])){z-index:5}
.box-heading{height:var(--a-box-header);display:flex;align-items:center;padding:0 5px 0 2px;gap:4px;min-width:0}
.box-toggle{
 flex:0 0 40px;min-width:40px;width:40px;height:40px;padding:0;
 display:grid;place-items:center;border:0;border-radius:8px;
 background:transparent;color:var(--a-subtle);cursor:pointer;
}
html[data-ui-input="hover"] .box-toggle:hover:not(:disabled){background:var(--a-accent-soft)}
.chevron{display:grid;place-items:center;transform:rotate(-90deg);transition:transform .12s;pointer-events:none}
.box-toggle[aria-expanded=true] .chevron{transform:rotate(0)}
.box-title{
 margin:0;min-width:0;display:flex;gap:6px;align-items:center;
 font-size:12px;line-height:18px;font-weight:700;
 color:inherit;cursor:default;user-select:none;-webkit-user-select:none;
}
.box-name{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.box-summary{flex:1;min-width:0;height:100%;display:flex;align-items:center;justify-content:flex-end;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;font-size:10px;color:var(--a-subtle);text-align:right;cursor:default}
.box-more{flex:none;padding:0;width:36px;height:38px;min-height:38px;min-width:36px;border:0;border-radius:8px;background:transparent;font-size:13px;color:var(--a-subtle)}
@media(any-pointer:coarse){
 .box-toggle{position:relative;flex-basis:40px}
 .box-toggle::before{content:"";position:absolute;inset:-2px;touch-action:manipulation}
 .box-more{height:40px;min-height:40px}
}
.box-body{padding:8px 12px 13px;border-top:1px solid var(--a-border);font-size:12px}
.box-body[hidden],.box-more-menu[hidden],.features-panel[hidden],.layer-page[hidden]{display:none!important}
.box-more-menu{
 position:absolute;z-index:6;right:6px;top:calc(var(--a-box-header) - 2px);
 width:min(248px,calc(100% - 12px));max-height:min(228px,55dvh);
 overflow-y:auto;overscroll-behavior:contain;
 border:1px solid var(--a-border-strong);border-radius:11px;
 padding:7px;display:flex;flex-direction:column;gap:3px;
 background:var(--a-surface);box-shadow:0 10px 26px #33497633,0 2px 6px #40526E19;
}
.box-more-menu[data-placement="above"]{top:var(--box-menu-above,-134px);bottom:auto}
.box-more-menu button{font-size:12px;min-height:40px;width:100%;text-align:left}
.box-more-menu span{font-size:10px;line-height:1.35;padding:5px 7px;align-self:stretch;color:var(--a-subtle)}
.box-body>label{margin:5px 0 9px}
.box-body #brush{min-height:34px;margin-top:4px}
.scalar-row{display:grid;grid-template-columns:auto minmax(60px,1fr) 61px auto;align-items:center;gap:5px;margin:8px 0 12px}
.scalar-row label{margin:0}.scalar-row input{margin:0}.scalar-row input[type=number]{height:34px;padding:2px 5px}.scalar-row span{font-size:10px}
.box-body .checkbox-line{display:flex;align-items:center;gap:7px;min-height:31px}
.unavailable{display:inline-flex;padding:8px;color:var(--a-subtle);border:1px dashed var(--a-border);border-radius:8px;width:100%;font-size:11px}
.box-actions{display:grid;grid-template-columns:1fr 1fr;gap:6px}
.box-actions button{font-size:11px;min-height:34px}
.width-control{padding:0}
.layer-list{max-height:205px;overflow:auto;display:grid;gap:4px;margin:6px 0 9px}
.layer-row{min-height:44px;border-radius:8px;border:1px solid var(--a-border);border-left:3px solid transparent;text-align:left;background:#fff;padding:8px}
.layer-row[aria-pressed=true]{border-left-color:var(--a-accent);background:var(--a-accent-soft);border-color:var(--a-border-strong)}
.layer-state{color:var(--a-focus)}
.commands{position:relative;inset:auto;width:100%;height:var(--a-strip);min-height:var(--a-strip);padding:4px 6px calc(4px + env(safe-area-inset-bottom,0px));background:#fff;border-top:1px solid var(--a-border);display:flex;gap:5px;z-index:1}
.commands button{min-width:0;flex:1;min-height:40px;border:1px solid transparent;background:transparent;border-radius:8px;font-size:19px;line-height:20px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:0;padding:2px}
.commands button span{display:block;font-size:9px;line-height:12px;white-space:nowrap}
.commands button[aria-expanded=true]{background:var(--a-accent-soft)}
#splitter{right:var(--workspace);top:var(--top);bottom:var(--a-strip);width:7px;background:transparent;z-index:9;display:flex;align-items:center;justify-content:center}
#splitter:before{content:'';position:absolute;inset:0 auto 0 3px;width:1px;background:#c9ccc2}
html[data-ui-input="hover"] #splitter:hover,#splitter:focus-visible,#splitter.dragging{background:#9cb5f533}
.resize-grip{position:relative;width:22px;min-height:64px;background:var(--a-surface-soft);border:1px solid var(--a-border-strong);box-shadow:0 2px 7px #4442;border-radius:9px;display:flex;align-items:center;justify-content:center;font-size:15px;color:var(--a-subtle);pointer-events:none}
.layer-page{flex:1;min-height:0;display:flex;flex-direction:column;background:var(--a-surface-soft);padding:12px 12px 8px;overflow:hidden}
.layer-page-head{display:flex;justify-content:space-between;align-items:center;padding:4px 4px 12px;border-bottom:1px solid var(--a-border)}
.layer-page-head small{font-size:9px;letter-spacing:1.1px;color:var(--a-subtle)}
.layer-page-head h2{font-size:19px;font-weight:720;margin:4px 0 0}
#closeLayerPage{font-size:21px;min-width:39px;min-height:39px}
.layer-page-meta{padding:12px 4px;font-size:12px;color:var(--a-subtle)}
.layer-page-meta strong{color:var(--a-text)}
.layer-page-list{flex:1;min-height:0;max-height:none;overflow-y:auto;align-content:start}
.layer-page-actions{padding:9px 0;border-top:1px solid var(--a-border)}
.layer-page-actions button{width:100%;min-height:41px;background:var(--a-accent-soft)}
.layer-page-actions p{font-size:10px;color:var(--a-subtle);margin-bottom:2px}
.features-panel{position:fixed;z-index:17;left:var(--features-left,calc(var(--rail) + 8px));top:var(--features-top,calc(var(--top) + 8px));width:var(--features-width,min(340px,calc(100vw - var(--rail) - 18px)));max-height:var(--features-max-height,calc(100dvh - var(--top) - 20px));overflow-y:auto;overscroll-behavior:contain;padding:12px;background:var(--a-surface);border:1px solid var(--a-border);border-radius:14px;box-shadow:var(--a-elevation)}
.features-header{display:flex;align-items:center;justify-content:space-between;padding:0 4px 8px;font-size:14px}
.features-header button{font-size:20px;border:0}
.feature-categories{display:grid;gap:4px}
 .feature-category{min-height:40px;width:100%;font-size:12px;text-align:left;display:flex;align-items:center;justify-content:space-between;padding:8px 12px}
.feature-category[data-group-start=true]{margin-top:9px;border-top:2px solid var(--a-border)}
.feature-actions button{display:block;width:100%;text-align:left;min-height:40px;margin:5px 0}
.feature-actions h3{font-size:14px}
.qa-review{position:fixed;z-index:15;top:calc(var(--top) + 8px);left:calc(var(--rail) + 12px);width:min(400px,calc(100vw - var(--rail) - 24px));max-height:calc(100dvh - var(--top) - 16px);overflow:auto;padding:7px 11px;background:var(--a-surface);box-shadow:var(--a-elevation)}
.qa-review:not([open]){width:max-content;max-width:calc(100vw - 95px)}
.qa-review>summary{font-size:12px;font-weight:700}
.qa-review .qa-panel{border:0;padding:0}
.qa-review .qa-panel ol{font-size:11px}
body.right-collapsed main#canvasArea,body.right-overlay main#canvasArea{margin-right:0}
body.right-collapsed .right-dock{width:var(--workspace);top:auto;height:var(--a-strip);bottom:0}
body.right-collapsed #workspace,body.right-collapsed #layerPage,body.right-collapsed #splitter{display:none}
body.right-overlay .right-dock{box-shadow:-9px 0 26px #2c302720}
@media(any-pointer:coarse){
  :root{--a-target:44px}
  .rail .tool-button{min-height:52px}
  .box-toggle,.box-more{min-height:40px}
  .commands button{min-height:40px}
  #splitter{width:12px}
  .resize-grip{width:26px;min-height:74px}
}
@media(max-height:680px){.rail .tool-button{min-height:44px}.rail .tool-caption{font-size:8px}.rail .all{min-height:47px!important}}
@media(max-width:760px){
 :root{--rail:56px;--top:44px;--bottom:52px}
 body{overflow:hidden}
 .topbar{height:var(--top);padding:0 6px;gap:3px}
 .brand-sub{display:none}.brand strong{font-size:14px}.brand-mark{flex-basis:27px;width:27px;height:27px}
 .topbar button{font-size:10px;padding:3px 5px;min-height:32px}
 .topbar #saveState{font-size:9px;overflow:hidden;text-overflow:ellipsis}
 .topbar button span{display:none}
 .rail{bottom:calc(var(--bottom) + env(safe-area-inset-bottom));padding:5px 3px;overflow-y:auto;overscroll-behavior:contain;scrollbar-width:none}
 .rail .tool-button{min-height:44px;padding:2px}.rail .tool-caption{font-size:8px}
 .rail .tool-glyph{font-size:19px;line-height:19px}
 /* Compact paint shortcuts: a legible single-line caption below a pictogram. */
 .rail .compact-shortcut{
  display:flex;flex:none;flex-direction:column;align-items:center;justify-content:center;
  width:100%;height:46px;min-height:46px;gap:2px;margin:0;padding:3px 0;
  border:1px solid var(--a-border);border-radius:10px;
  background:var(--a-surface-soft);color:var(--a-subtle);
  font-size:9px;line-height:11px;white-space:nowrap;
 }
 .rail .compact-shortcut .ui-icon{width:18px;height:18px}
 .rail .compact-shortcut span{display:block;white-space:nowrap;letter-spacing:-.15px}
 .rail .all{min-height:44px!important}
 main#canvasArea,body.right-overlay main#canvasArea{margin:var(--top) 0 var(--bottom) var(--rail);height:calc(100dvh - var(--top) - var(--bottom));padding:0}
 .canvas-top{padding:4px 8px;min-height:70px;gap:3px}
 #status{font-size:10px;min-width:0;flex:1 1 100%;max-height:30px;overflow:auto}
 .document-actions{gap:3px}.document-actions button{font-size:9px;min-height:28px;padding:3px 5px}
 .surface{max-width:calc(100% - 14px);width:100%;margin:auto}
 .right-dock,body.right-overlay .right-dock{top:auto;bottom:calc(var(--bottom) + env(safe-area-inset-bottom));left:var(--rail);right:env(safe-area-inset-right);width:auto;height:43dvh;box-shadow:0 -4px 18px #2a332522;opacity:0;transform:translate3d(0,calc(100% + 5px),0);pointer-events:none;transition:transform .14s ease,opacity .14s ease;contain:layout paint}
 .right-dock.open{opacity:1;transform:none;pointer-events:auto}
 .right-dock #workspace{height:100%;flex:1;inset:auto;padding:0;min-width:0;width:100%}
 .right-dock .commands{display:none}
 .right-dock .layer-page{height:100%}
 #splitter{display:none}
 .bottom{display:flex;z-index:12}
 .qa-review{left:calc(var(--rail) + 4px);top:calc(var(--top) + 3px)}
 body.right-collapsed .right-dock{height:43dvh;top:auto;bottom:calc(var(--bottom) + env(safe-area-inset-bottom));width:auto}
}
/* On a 360 × 640 phone every core action must remain visible without
   scrolling the tool rail. Keep 44px tap targets; remove only inter-row gaps. */
@media(max-width:760px) and (max-height:680px){
 .rail{gap:0;padding-top:3px;padding-bottom:3px}
 .rail .compact-shortcut{height:44px;min-height:44px}
 .rail .tool-button{min-height:44px}
}
@media(max-width:760px) and (orientation:landscape){.right-dock,body.right-collapsed .right-dock{height:48dvh}}
@media(prefers-reduced-motion:reduce){.right-dock,.chevron,button{transition:none!important}}

.resize-grip{pointer-events:auto;cursor:ew-resize}
#featuresCategories[hidden],#featuresActions[hidden]{display:none!important}

/* In overlay mode, keep document operations on the exposed side of Canvas.
   This avoids the dock intercepting creation/open/save controls on narrow tablets. */
@media(min-width:761px){
 body.right-overlay .canvas-top{flex-direction:column;align-items:flex-start;gap:5px;min-height:88px}
 body.right-overlay .canvas-top #status{flex:none;min-width:0;width:max(170px,calc(100% - var(--workspace) - 22px))}
 body.right-overlay .canvas-top .document-actions{max-width:calc(100% - var(--workspace) - 22px)}
}

/* M08 navigation: separate responsive view controls from the fixed M07 panels. */
.canvas-view-strip{display:flex;align-items:center;justify-content:center;gap:5px;flex-wrap:wrap;padding:5px 9px;max-width:100%;background:#fff9;border-bottom:1px solid var(--a-border);font-size:12px}
.canvas-view-strip button{min-width:38px;min-height:34px;padding:5px 9px;border-radius:8px;border:1px solid var(--a-border);background:var(--a-surface,#fff);color:var(--a-text,#253047);font-size:12px}
.canvas-view-strip button:focus-visible{outline:2px solid var(--a-accent,#708fff)}
.view-number-label{display:flex;gap:3px;align-items:center;font-size:12px}
.view-number-label input{width:57px;max-width:65px;min-height:33px;border:1px solid var(--a-border);border-radius:7px;background:#fff;color:#253047;text-align:center}
.commands button[aria-pressed=true]{background:var(--a-accent-soft,#e9eeff)}
@media(max-width:760px){.canvas-view-strip{justify-content:flex-start;width:100%;overflow-x:auto;flex-wrap:nowrap;flex:none}.canvas-view-strip button{flex:none}.view-number-label{flex:none}}

/* M08 document geometry UI. The overlay is view-only and never a raster layer. */
.surface{position:relative}
.crop-overlay{position:absolute;inset:0;width:100%;height:100%;pointer-events:none;overflow:visible}
.crop-overlay[hidden]{display:none!important}
#cropPolygon{stroke:#e6a62e;stroke-width:2;stroke-dasharray:7 4;vector-effect:non-scaling-stroke;fill:#f5c85422}
.crop-handle{fill:white;stroke:#d38a13;stroke-width:3;vector-effect:non-scaling-stroke;pointer-events:all;cursor:move;touch-action:none;filter:drop-shadow(0 1px 2px #2334)}
.geometry-dialog{position:fixed;left:max(80px,calc(var(--rail) + 12px));top:calc(var(--top) + 78px);margin:0;z-index:20;width:min(348px,calc(100vw - var(--rail) - 30px));max-height:calc(100dvh - var(--top) - 90px);overflow:auto;background:var(--a-surface);color:var(--a-text);border:1px solid var(--a-border-strong);border-radius:14px;padding:16px;box-shadow:0 14px 36px #24324638}
.geometry-dialog h2{font-size:17px;margin:0 0 7px}.geometry-dialog p{font-size:12px;margin:6px 0 12px;color:var(--a-subtle)}
.geometry-inputs{display:grid;grid-template-columns:1fr 1fr;gap:9px}.geometry-inputs label{display:flex;flex-direction:column;gap:4px;font-size:12px}.geometry-inputs input,.geometry-inputs select{width:100%;min-height:35px;padding:4px 7px;border:1px solid var(--a-border-strong);background:white;border-radius:8px;color:var(--a-text)}
.geometry-dialog .export-actions{display:flex;justify-content:flex-end;gap:9px;margin-top:12px}
.geometry-dialog .export-actions button{min-height:38px;border-radius:9px;border:1px solid var(--a-border);padding:6px 12px;background:white}
.geometry-dialog #geometryApply{background:#ffe49b;border-color:#e9bd53}

/* M10 brush controls: compact, scroll with the existing Brush workspace box. */
.m10-presets{display:grid;gap:7px;min-width:0}
.m10-presets>label,.m10-brush-settings>label{display:grid;gap:3px;min-width:0;font-size:12px}
.m10-presets input[type="search"]{width:100%;min-width:0}
.m10-preset-actions{display:flex;gap:4px;flex-wrap:wrap}
.m10-preset-actions button{flex:1 1 40%;min-height:35px;padding:5px 7px;font-size:11px}
#brushLibraryStatus{font-size:11px;line-height:1.45;overflow-wrap:anywhere;color:var(--a-subtle)}
.m10-brush-settings{display:grid;gap:7px;margin-block:8px}
.m10-brush-settings label:not(.checkbox-line) input{width:100%;min-width:0}
.m10-brush-settings>.workspace-range{margin:0;font-size:12px}
.m10-brush-settings .checkbox-line{display:flex;align-items:center;gap:5px}
#documentInfoDialog textarea{width:100%;box-sizing:border-box;font:inherit}
#documentInfoDialog h3{margin-bottom:4px}
#canvasTemplateForm{border-top:1px solid var(--a-border);margin-top:12px}
#canvasTemplateForm label{display:inline-flex;flex-wrap:wrap;align-items:center;gap:6px}
.pixel-grid{position:absolute;inset:0;width:100%;height:100%;pointer-events:none;opacity:.65;z-index:1}
.pixel-grid[hidden]{display:none!important;pointer-events:none}
.pixel-coordinates{position:absolute;right:8px;bottom:8px;z-index:1;background:#fff;color:#27354b;padding:3px 7px;border-radius:4px;pointer-events:none;font-variant-numeric:tabular-nums}
.brush-cursor{position:absolute;top:0;left:0;box-sizing:border-box;border:1px solid #151b2a;box-shadow:0 0 0 1px #fff;border-radius:50%;pointer-events:none;z-index:2}
.brush-cursor::after{content:"";position:absolute;left:50%;top:50%;width:3px;height:3px;border-radius:50%;background:#151b2a;box-shadow:0 0 0 1px #fff;transform:translate(-50%,-50%)}

#maskThumbnail { padding: 2px; vertical-align: middle; }
#maskThumbnail[aria-pressed="true"] { outline: 2px solid #43bfea; outline-offset: 2px; }
#maskThumbnail canvas { display: block; width: 48px; height: 48px; }
#maskEditingBar:not([hidden]), #historyBrushBar:not([hidden]) { display: flex; flex-wrap: wrap; gap: .35rem; align-items: center; }
#historyBrushBar > .workspace-range { flex: 0 1 190px; margin: 0; }
#maskEditingBar button[aria-pressed="true"] { outline: 2px solid #43bfea; outline-offset: -2px; }

.layer-blend-dialog { position: fixed; inset: auto auto 1rem 1rem; z-index: 30; max-width: min(90vw, 26rem); }
.layer-blend-dialog form { display: grid; gap: .6rem; }
.layer-blend-dialog label { display: flex; gap: .6rem; align-items: center; justify-content: space-between; }
.layer-blend-dialog menu { display: flex; gap: .6rem; margin: 0; padding: 0; }

.layer-pick-dialog fieldset { display: grid; gap: .35rem; max-height: 40dvh; overflow: auto; }
.layer-pick-dialog label { justify-content: flex-start; }

#layerDrawingThumbnail { width: 36px; height: 36px; vertical-align: middle; background: #dedfe2; border: 1px solid #9998; }
.brush-cursor[data-tip-mask] { border: 0; box-shadow: none; }
.brush-cursor[data-tip-mask]::before {
  content: "";
  position: absolute;
  inset: 0;
  background: #10122077;
  mask: var(--brush-cursor-mask) 50% / 100% 100% no-repeat;
  outline: 1px solid white;
}

ui/workspaceControls.css:
select.workspace-choice-source { display: none !important }
.workspace-choice {
  display: inline-flex;
  align-items: center;
  justify-content: space-between;
  gap: 6px;
  max-width: 100%;
  min-height: 40px;
  padding-inline: 6px;
  text-align: start;
  border: 0;
  border-bottom: 1px solid var(--a-border-strong, #a5b0c3);
  border-radius: 0;
  background: transparent;
  color: inherit;
}
.workspace-choice > span { min-width: 0; overflow-wrap: anywhere }
.workspace-choice .ui-icon { flex: none; width: 16px; height: 16px }
.workspace-choice[hidden], .workspace-options:not(:popover-open) { display: none }
.workspace-options {
  position: fixed;
  inset: auto;
  margin: 0;
  padding: 4px;
  box-sizing: border-box;
  overflow: auto;
  overscroll-behavior: contain;
  touch-action: pan-y;
  background: var(--a-surface, #fff);
  color: var(--a-text, #222c40);
  border: 1px solid var(--a-border, #c7d0df);
  border-radius: 9px;
  box-shadow: 0 8px 26px #19294330;
}
.workspace-options [role=option] {
  display: flex;
  align-items: center;
  min-height: 42px;
  padding: 4px 8px;
  border-radius: 5px;
  cursor: pointer;
}
.workspace-options [role=option][aria-selected=true] { font-weight: 700 }
.workspace-options [role=option][aria-selected=true]::before { content: '✓'; margin-inline-end: 6px }
.workspace-options [role=option][aria-disabled=true] { opacity: .47; cursor: default }
.workspace-options [role=option].active { outline: 2px solid var(--a-focus, #565aad); outline-offset: -2px }
.workspace-range:not([hidden]) {
  display: grid;
  grid-template-columns: var(--range-step-width, 36px) minmax(0, 1fr) var(--range-step-width, 36px);
  gap: 0 5px;
  align-items: center;
  min-width: 0;
}
.workspace-range-from-label { margin-block: 5px; font-size: 13px }
.workspace-range-header {
  grid-column: 1 / -1;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 6px;
  min-width: 0;
}
.workspace-range .workspace-range-header > label {
  display: block;
  min-width: 0;
  margin: 0;
  font-size: inherit;
  overflow-wrap: anywhere;
}
.workspace-range-value {
  display: flex;
  align-items: center;
  flex: 0 0 auto;
  color: inherit;
  font-variant-numeric: tabular-nums;
}
.workspace-range-value > input[type=number] {
  appearance: textfield;
  width: 7ch;
  min-height: 30px;
  margin: 0;
  padding: 0 3px;
  text-align: end;
  color: inherit;
  background: transparent;
  border: 0;
  border-radius: 4px;
  cursor: text;
}
.workspace-range-value > input[type=number]::-webkit-inner-spin-button,
.workspace-range-value > input[type=number]::-webkit-outer-spin-button { appearance: none; margin: 0 }
.workspace-range-value > input[type=number]:focus {
  background: var(--a-surface, #fff);
  outline: 1px solid var(--a-focus, #565aad);
  outline-offset: -1px;
}
.workspace-range-value > input[type=number]:focus-visible { outline-width: 2px }
.workspace-range-value > input[type=number]:disabled { opacity: .55; cursor: default }
.workspace-range > input[type=range] { grid-area: 2 / 2; width: 100%; min-width: 0; min-height: 28px; margin: 0 }
/* Keep legacy output nodes for existing value updates, but never render duplicate values below the slider. */
.workspace-range > output { display: none !important }
.workspace-range-minus, .workspace-range-plus { grid-row: 2; min-height: 36px; padding: 0 }
.workspace-range-minus { grid-column: 1 }
.workspace-range-plus { grid-column: 3 }

color/color.css:
/* M09 Color / Aurora. The first interaction is choosing a color.
 * Secondary settings use native disclosures; never squeeze four parallel tabs into a narrow dock.
 * The SV square and its handle are mathematically INSIDE the hue ring's empty center.
 */
.color-workbench{min-width:0;display:flex;flex-direction:column;gap:12px;padding:3px 0 6px;color:var(--a-text)}
.color-workbench *{box-sizing:border-box}
.color-current{display:grid;grid-template-columns:46px minmax(0,1fr) 34px auto;align-items:center;gap:9px;padding:10px 9px;border-radius:12px;background:var(--a-surface-soft);border:1px solid var(--a-border)}
.color-chip{display:block;width:46px;height:43px;min-width:0;min-height:0;padding:0;border-radius:10px;border:2px solid white;box-shadow:0 0 0 1px var(--a-border-strong),0 2px 6px #30425928;cursor:pointer}
.color-chip:focus-visible{outline:3px solid var(--a-focus);outline-offset:3px}
.color-previous{width:34px;height:34px;border-radius:8px}
.color-previous-label{font-size:10px;white-space:nowrap;color:var(--a-subtle)}
.color-describe{display:flex;flex-direction:column;gap:4px;min-width:0}
.color-describe strong{font-size:11px;font-weight:650;color:var(--a-subtle)}
.color-describe output{font-size:14px;font-weight:750;letter-spacing:.03em;font-variant-numeric:tabular-nums;white-space:nowrap}
.color-primary{display:flex;flex-direction:column;gap:7px}
.color-picker{position:relative;width:min(252px,100%);height:auto;aspect-ratio:1;margin:2px auto 3px;touch-action:none;user-select:none;isolation:isolate}
/* Use closest-side (actual circle radius) for the mask. The former farthest-corner percentage stop made the color band too wide. */
.color-ring{--hue-ring-width:22px;position:absolute;inset:0;border-radius:50%;background:conic-gradient(from 90deg,#ff0000,#ffff00,#00ff00,#00ffff,#0000ff,#ff00ff,#ff0000);-webkit-mask:radial-gradient(circle closest-side at center,transparent calc(100% - var(--hue-ring-width) - 1px),#000 calc(100% - var(--hue-ring-width)));mask:radial-gradient(circle closest-side at center,transparent calc(100% - var(--hue-ring-width) - 1px),#000 calc(100% - var(--hue-ring-width)));touch-action:none}
/* Visual cutout fallback for engines that do not support CSS masks. */
.color-ring::after{content:"";position:absolute;inset:var(--hue-ring-width);border-radius:50%;background:var(--a-surface);pointer-events:none}
.color-ring:focus-visible{outline:3px solid var(--a-focus);outline-offset:4px}
.color-ring-marker{position:absolute;left:94%;top:50%;width:18px;height:18px;transform:translate(-50%,-50%);border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 1.5px #263144,0 1px 5px #26314488;z-index:2;pointer-events:none}
.color-plane{position:absolute;left:27%;top:27%;width:46%;height:46%;border-radius:8px;background:var(--pure,#ff0000);box-shadow:0 1px 4px #16294d3b,0 0 0 1px #cad3df;touch-action:none;cursor:crosshair}
.color-plane-white,.color-plane-black{position:absolute;inset:0;border-radius:inherit;pointer-events:none}
.color-plane-white{background:linear-gradient(to right,#fff,transparent)}
.color-plane-black{background:linear-gradient(to top,#000,transparent)}
