  const x0=Math.max(left,mask.x),x1=Math.min(right,mask.x+mask.width);
  const y0=Math.max(top,mask.y),y1=Math.min(bottom,mask.y+mask.height);
  if(x0>=x1||y0>=y1)return outside;
