      id:original?.id??draftId,name:name.value.trim()||defaultGuide().name,
      kind:kind.value as ArtworkGuide['kind'],origin:point(0),vanishing:[point(1),point(2)],activeAxis:Math.min(+axis.value,axisCount()-1),
