      await store.save(last.filter(item=>item.id!==id),'定規・ガイドを削除');
      refresh();
    },output),
    button('次の一筆だけ吸着を解除',()=>{
      drawing?.bypassNextGuide();target.textContent='次の一筆は吸着を解除します。';
    },output),
    target,output
  );
  host.append(panel);refresh();
  return {refresh};
}

