    const occupied=new Set(remaining.map(item=>item.id));
    const safe=imported.map(item=>{
      let id=item.id;
      while(occupied.has(id))id=uid();
      occupied.add(id);
      return {...item,id};
    });
    const next=[...remaining,...safe];
